/* Card set: RuneScape (generated from the approved roster-final.csv by the RS3 build).
   (runescape-3.js exceeds the comfortable push size, so the remaining cards live in
   runescape-3-additions.js, which must stay directly after 'runescape-3.js' in sets/manifest.js.) */
CardSets.register({"id":"runescape-3","name":"RuneScape","code":"RS3","description":"480 cards from Gielinor — its skills and capes, bosses, quests, cities, gods, gear, monsters and pastimes, from the Completionist Cape and the Blue Partyhat to Telos, Prifddinas and a full set of partyhats. RS3 only; Old School is a story for another set.","theme":{"primary":"#37503f","secondary":"#c9a227","artBackground":"#efe8d8","artFit":"contain"},"pack":{"name":"RuneScape Pack","emblem":"⚔️","skin":"runescape"},"cards":[{"name":"Completionist Cape","rarity":"chase","id":"completionist-cape","subtitle":"Skills","details":"The ultimate cape, earned by finishing every quest, task set, and major achievement on offer: mastery beyond maxing skills.","image":"https://runescape.wiki/images/thumb/Completionist_cape_detail.png/640px-Completionist_cape_detail.png"},{"name":"Blue Partyhat","rarity":"chase","id":"blue-partyhat","subtitle":"Items","details":"The rarest of the partyhats pulled from Christmas crackers long ago, a paper crown that became the ultimate symbol of wealth.","image":"https://runescape.wiki/images/Blue_partyhat_detail.png"},{"name":"Telos, the Warden","rarity":"chase","id":"telos-the-warden","subtitle":"Bosses","details":"Anima guardian at the Heart of Gielinor who grows stronger across enrage streaks, testing endurance, precision and nerve.","image":"https://runescape.wiki/images/thumb/Telos%2C_the_Warden.png/640px-Telos%2C_the_Warden.png"},{"name":"Zamorak, Lord of Chaos","rarity":"chase","id":"zamorak-lord-of-chaos","subtitle":"Bosses","details":"The god of chaos fought beneath the Wilderness, unleashing runes, infernal power and phases that punish slow reactions.","image":"https://runescape.wiki/images/thumb/Zamorak%2C_Lord_of_Chaos.png/640px-Zamorak%2C_Lord_of_Chaos.png"},{"name":"Rasial, the First Necromancer","rarity":"chase","id":"rasial-the-first-necromancer","subtitle":"Bosses","details":"The First Necromancer in the City of Um, commanding death, souls and skeletal servants in a fast, punishing duel.","image":"https://runescape.wiki/images/thumb/Rasial%2C_the_First_Necromancer.png/640px-Rasial%2C_the_First_Necromancer.png"},{"name":"Zaros","rarity":"chase","id":"zaros","subtitle":"Gods & NPCs","details":"The Empty Lord, a transcendent god of fate and control who built the Zarosian empire and now seeks to become an Elder God.","image":"https://runescape.wiki/images/thumb/Zaros.png/640px-Zaros.png"},{"name":"Seren Godbow","rarity":"chase","id":"seren-godbow","subtitle":"Gear","details":"Tier 92 two-handed bow assembled from drops by Telos in the Heart of Gielinor, famed for its crystal power and huge Ranged damage.","image":"https://runescape.wiki/images/thumb/Seren_godbow_detail.png/512px-Seren_godbow_detail.png"},{"name":"While Guthix Sleeps","rarity":"chase","id":"while-guthix-sleeps","subtitle":"Quests","details":"The first Grandmaster quest: Lucien steals the Stone of Jas, the Dragonkin stir, and the heroes of Gielinor fall in a battle that reshapes the world.","image":"https://runescape.wiki/images/thumb/Lucien_and_the_Stone_of_Jas.png/640px-Lucien_and_the_Stone_of_Jas.png?d1286"},{"name":"Prifddinas","rarity":"chase","id":"prifddinas","subtitle":"Locations","details":"The elven capital in Tirannwn, rebuilt in crystal around the Tower of Voices, home to eight clans, a lodestone and the Max Guild.","image":"https://runescape.wiki/images/thumb/Prifddinas.png/640px-Prifddinas.png"},{"name":"The World Wakes","rarity":"chase","id":"the-world-wakes","subtitle":"Quests","details":"The World Guardian is chosen as Guthix falls to Sliske. A Grandmaster quest that ends the Fourth Age and begins the Sixth Age of Gielinor.","image":"https://runescape.wiki/images/The_World_Wakes.png?864e5"},{"name":"Necromancy","rarity":"legendary","id":"necromancy","subtitle":"Skills","details":"Communing with the dead in the City of Um through rituals and conjures, commanding ghostly allies against living enemies.","image":"https://runescape.wiki/images/thumb/Necromancy_cape_detail.png/640px-Necromancy_cape_detail.png"},{"name":"Max Cape","rarity":"legendary","id":"max-cape","subtitle":"Skills","details":"Awarded for reaching level 99 in every skill, this cape can carry the perks of other skillcapes and marks a master of all trades.","image":"https://runescape.wiki/images/Max_cape_detail.png"},{"name":"Nex","rarity":"legendary","id":"nex","subtitle":"Bosses","details":"Zarosian general sealed in the Ancient Prison, fighting through smoke, shadow, blood, ice and wrath phases.","image":"https://runescape.wiki/images/thumb/Nex.png/640px-Nex.png"},{"name":"Vorago","rarity":"legendary","id":"vorago","subtitle":"Bosses","details":"A colossal anima guardian born of the world itself, faced in his borehole north of Falador in team phases that rotate weekly.","image":"https://runescape.wiki/images/thumb/Vorago.png/512px-Vorago.png"},{"name":"Solak","rarity":"legendary","id":"solak","subtitle":"Bosses","details":"A grove guardian corrupted by darkness on the Lost Grove, fought alongside Merethiel in a demanding team encounter.","image":"https://runescape.wiki/images/thumb/Solak%2C_Guardian_of_the_Grove.png/640px-Solak%2C_Guardian_of_the_Grove.png"},{"name":"Kerapac, the Bound","rarity":"legendary","id":"kerapac-the-bound","subtitle":"Bosses","details":"A dragonkin elder bound by the Elder Gods beneath Senntisten, wielding time, lightning and his staff against intruders.","image":"https://runescape.wiki/images/thumb/Kerapac%2C_the_bound.png/640px-Kerapac%2C_the_bound.png"},{"name":"Raksha, the Shadow Colossus","rarity":"legendary","id":"raksha-the-shadow-colossus","subtitle":"Bosses","details":"A shadow colossus chained on Anachronia, breaking free to charge, swipe and flood its arena with shadow anima.","image":"https://runescape.wiki/images/Raksha%2C_the_Shadow_Colossus.png"},{"name":"TzKal-Zuk","rarity":"legendary","id":"tzkal-zuk","subtitle":"Bosses","details":"Successor to TzTok-Jad at the TzekHaar front, leading waves of obsidian warriors before duelling challengers himself.","image":"https://runescape.wiki/images/thumb/TzKal-Zuk.png/640px-TzKal-Zuk.png"},{"name":"The Ambassador","rarity":"legendary","id":"the-ambassador","subtitle":"Bosses","details":"A corrupted envoy serving Xau-Tak at the Shadow Reef, raising undead, portals and devastating black-hand attacks.","image":"https://runescape.wiki/images/The_Ambassador.png"},{"name":"Ritual of the Mahjarrat","rarity":"legendary","id":"ritual-of-the-mahjarrat","subtitle":"Quests","details":"The Mahjarrat gather for their ritual of rejuvenation as the Dragonkin descend. A Grandmaster quest tying together years of storylines.","image":"https://runescape.wiki/images/Ritual_of_the_Mahjarrat.png?b2462"},{"name":"Fate of the Gods","rarity":"legendary","id":"fate-of-the-gods","subtitle":"Quests","details":"Journey to Freneskae, homeworld of the Mahjarrat, and decide whether Zaros returns to Gielinor. A Grandmaster quest of gods and elder halls.","image":"https://runescape.wiki/images/thumb/Fate_of_the_Gods.png/640px-Fate_of_the_Gods.png?bd99b"},{"name":"Sliske's Endgame","rarity":"legendary","id":"sliske-s-endgame","subtitle":"Quests","details":"Sliske's game for the Stone of Jas ends in his labyrinth, where gods race for the stone and the player faces Sliske himself. A Grandmaster finale.","image":"https://runescape.wiki/images/thumb/Sliske%27s_Endgame.png/640px-Sliske%27s_Endgame.png?04f3c"},{"name":"Brink of Extinction","rarity":"legendary","id":"brink-of-extinction","subtitle":"Quests","details":"The TokHaar reveal the Brink of Extinction beneath the Elder Kiln, forged to remake the world. A Grandmaster quest ending the TzHaar storyline.","image":"https://runescape.wiki/images/thumb/Fight_Cauldron.png/640px-Fight_Cauldron.png?699ef"},{"name":"Desert Treasure","rarity":"legendary","id":"desert-treasure","subtitle":"Quests","details":"Recover the four diamonds of Azzanadra from ancient guardians to free him from his pyramid prison, unlocking the Ancient Magicks spellbook.","image":"https://runescape.wiki/images/thumb/Desert_Treasure.png/640px-Desert_Treasure.png?86c0f"},{"name":"Senntisten","rarity":"legendary","id":"senntisten","subtitle":"Locations","details":"The ancient Zarosian capital beneath the Kharidian Desert, a vast ruined city of temples, archives and the Elder God Wars front.","image":"https://runescape.wiki/images/thumb/City_of_Senntisten.png/640px-City_of_Senntisten.png"},{"name":"City of Um","rarity":"legendary","id":"city-of-um","subtitle":"Locations","details":"The ghostly city in the Underworld, home of the Necromancy ritual site, where souls gather beside the River Noumenon and Lake Mnemosyne.","image":"https://runescape.wiki/images/thumb/City_of_Um.png/640px-City_of_Um.png"},{"name":"Freneskae","rarity":"legendary","id":"freneskae","subtitle":"Locations","details":"The harsh homeworld of the Mahjarrat, a volcanic wasteland of lava and ash beneath a shattered sky, birthplace of Zaros and Seren lore.","image":"https://runescape.wiki/images/thumb/Freneskae.png/640px-Freneskae.png"},{"name":"The Arc","rarity":"legendary","id":"the-arc","subtitle":"Locations","details":"A chain of islands in the Eastern Lands across the Wushanko Isles, centred on Waiko, with ports, bamboo, turtles and uncharted isles.","image":"https://runescape.wiki/images/thumb/Waiko.png/640px-Waiko.png"},{"name":"Saradomin","rarity":"legendary","id":"saradomin","subtitle":"Gods & NPCs","details":"God of order and wisdom, first god to walk Gielinor in the Second Age and founder of the Saradominist faith across its kingdoms.","image":"https://runescape.wiki/images/thumb/Saradomin.png/640px-Saradomin.png"},{"name":"Guthix","rarity":"legendary","id":"guthix","subtitle":"Gods & NPCs","details":"God of balance who shaped Gielinor in the First Age, raised the World Gate, and placed the Edicts that banished the other gods.","image":"https://runescape.wiki/images/thumb/Guthix_%28god%29.png/640px-Guthix_%28god%29.png"},{"name":"Seren","rarity":"legendary","id":"seren","subtitle":"Gods & NPCs","details":"Goddess of the elves, a being of crystal and light whose song shaped Tirannwn and whose people revere her as their mother.","image":"https://runescape.wiki/images/thumb/Seren.png/640px-Seren.png"},{"name":"Jas","rarity":"legendary","id":"jas","subtitle":"Gods & NPCs","details":"Elder God of time, eldest of the five creators of the universe, whose great orb measures the revision of all existence.","image":"https://runescape.wiki/images/thumb/Jas.png/640px-Jas.png"},{"name":"Sliske","rarity":"legendary","id":"sliske","subtitle":"Gods & NPCs","details":"A shadowy Mahjarrat spymaster and servant of Jas who orchestrated assassinations, stole divine power, and toyed with heroes.","image":"https://runescape.wiki/images/thumb/Sliske_%28Missing%2C_Presumed_Death%29.png/640px-Sliske_%28Missing%2C_Presumed_Death%29.png"},{"name":"Zaros Godsword","rarity":"legendary","id":"zaros-godsword","subtitle":"Gear","details":"Tier 92 two-handed sword assembled from Telos drops in the Heart of Gielinor, wreathed in Zarosian purple energy and black holes.","image":"https://runescape.wiki/images/thumb/Zaros_godsword_detail.png/512px-Zaros_godsword_detail.png"},{"name":"Fractured Staff of Armadyl","rarity":"legendary","id":"fractured-staff-of-armadyl","subtitle":"Gear","details":"Tier 95 staff built from pieces dropped by Kerapac in Senntisten, channelling Armadyl's power and speeding up channelled abilities.","image":"https://runescape.wiki/images/thumb/Fractured_Staff_of_Armadyl_detail.png/512px-Fractured_Staff_of_Armadyl_detail.png"},{"name":"Bow of the Last Guardian","rarity":"legendary","id":"bow-of-the-last-guardian","subtitle":"Gear","details":"Tier 95 bow pieced together from Zamorak, Lord of Chaos in the Wilderness crater, the pinnacle reward of that enrage boss fight.","image":"https://runescape.wiki/images/thumb/Bow_of_the_Last_Guardian_detail.png/512px-Bow_of_the_Last_Guardian_detail.png"},{"name":"Eldritch Crossbow","rarity":"legendary","id":"eldritch-crossbow","subtitle":"Gear","details":"Tier 92 two-handed crossbow assembled from Ambassador drops in the Shadow Reef, able to split bolt effects with its special attack.","image":"https://runescape.wiki/images/thumb/Eldritch_crossbow_detail.png/512px-Eldritch_crossbow_detail.png"},{"name":"Staff of Sliske","rarity":"legendary","id":"staff-of-sliske","subtitle":"Gear","details":"Tier 92 two-handed staff dropped by Gregorovic in the Heart of Gielinor, summoning shadow wights with its special attack.","image":"https://runescape.wiki/images/thumb/Staff_of_Sliske_detail.png/512px-Staff_of_Sliske_detail.png"},{"name":"Tormented demon","rarity":"legendary","id":"tormented-demon","subtitle":"Monsters","details":"Tormented demons are powerful demons in the Ancient Guthix Temple, known for switching prayers and dropping dragon claws.","image":"https://runescape.wiki/images/thumb/Tormented_Demon.png/640px-Tormented_Demon.png"},{"name":"Glacor","rarity":"legendary","id":"glacor","subtitle":"Monsters","details":"Glacors are icy elemental creatures in the Glacor Cave near the Ritual Site, splitting into glacytes as they take damage.","image":"https://runescape.wiki/images/thumb/Glacor.png/640px-Glacor.png"},{"name":"Christmas Cracker","rarity":"legendary","id":"christmas-cracker","subtitle":"Items","details":"A festive cracker two players pull open together: one keeps the prize inside, and the other receives a partyhat.","image":"https://runescape.wiki/images/thumb/Christmas_cracker_detail.png/640px-Christmas_cracker_detail.png"},{"name":"Red Partyhat","rarity":"legendary","id":"red-partyhat","subtitle":"Items","details":"A red paper partyhat from a Christmas cracker of old, counted among the most valuable tradeable items in all of Gielinor.","image":"https://runescape.wiki/images/Red_partyhat_detail.png"},{"name":"Castle Wars","rarity":"legendary","id":"castle-wars","subtitle":"Activities","details":"A team capture-the-flag battle in a fortified arena, where two sides defend their standard and raid the enemy castle.","image":"https://runescape.wiki/images/thumb/Castle_Wars.png/640px-Castle_Wars.png"},{"name":"Treasure Trails","rarity":"legendary","id":"treasure-trails","subtitle":"Activities","details":"Clue scroll hunts that chain riddles, maps, puzzles and coordinates across Gielinor toward a casket of rare rewards.","image":"https://runescape.wiki/images/thumb/Clue_scroll_%28elite%29_detail.png/640px-Clue_scroll_%28elite%29_detail.png"},{"name":"Summoning","rarity":"epic","id":"summoning","subtitle":"Skills","details":"Binding spirits into pouches to call familiars that fight, carry goods, and grant effects, using charms gathered in combat.","image":"https://runescape.wiki/images/thumb/Summoning_cape_detail.png/640px-Summoning_cape_detail.png"},{"name":"Dungeoneering","rarity":"epic","id":"dungeoneering","subtitle":"Skills","details":"Delving the shifting floors of Daemonheim in a party, binding gear, solving rooms, and fighting bosses for chaotic rewards.","image":"https://runescape.wiki/images/thumb/Dungeoneering_cape_detail.png/640px-Dungeoneering_cape_detail.png"},{"name":"Invention","rarity":"epic","id":"invention","subtitle":"Skills","details":"Disassembling items for materials and augmenting gear with perks, machines, and devices powered by gathered inspiration.","image":"https://runescape.wiki/images/thumb/Invention_cape_detail.png/640px-Invention_cape_detail.png"},{"name":"Archaeology","rarity":"epic","id":"archaeology","subtitle":"Skills","details":"Excavating dig sites from Kharid-et to Stormguard Citadel, restoring damaged artefacts and uncovering relics of past ages.","image":"https://runescape.wiki/images/thumb/Archaeology_cape_detail.png/640px-Archaeology_cape_detail.png"},{"name":"Nex: Angel of Death","rarity":"epic","id":"nex-angel-of-death","subtitle":"Bosses","details":"Nex at her mightiest in the Ancient Prison, aided by her four mages in a seven-player battle for rare rewards.","image":"https://runescape.wiki/images/thumb/Nex%2C_Angel_of_Death.png/640px-Nex%2C_Angel_of_Death.png"},{"name":"Araxxor","rarity":"epic","id":"araxxor","subtitle":"Bosses","details":"A monstrous spider in the Araxyte Hive whose acid, darkness and web paths change the fight, ending with Araxxi.","image":"https://runescape.wiki/images/thumb/Araxxor.png/640px-Araxxor.png"},{"name":"Queen Black Dragon","rarity":"epic","id":"queen-black-dragon","subtitle":"Bosses","details":"The vast dragon beneath Rimmington, woken from slumber to breathe fire, summon shades and shift across platforms.","image":"https://runescape.wiki/images/thumb/Queen_Black_Dragon.png/640px-Queen_Black_Dragon.png"},{"name":"Corporeal Beast","rarity":"epic","id":"corporeal-beast","subtitle":"Bosses","details":"A devourer of souls haunting the caves beyond the Wilderness, famed for its huge health and sigil drops.","image":"https://runescape.wiki/images/thumb/Corporeal_Beast.png/640px-Corporeal_Beast.png"},{"name":"Kalphite King","rarity":"epic","id":"kalphite-king","subtitle":"Bosses","details":"Ruler of the Kalphite Hive who shifts between melee, ranged and magic forms and can fell fighters in one strike.","image":"https://runescape.wiki/images/thumb/Kalphite_King_%28Melee%29.png/640px-Kalphite_King_%28Melee%29.png"},{"name":"Seiryu the Azure Serpent","rarity":"epic","id":"seiryu-the-azure-serpent","subtitle":"Bosses","details":"The azure serpent of Aminishi, corrupted by black stone, coiling around its temple shrine as monks seek its freedom.","image":"https://runescape.wiki/images/thumb/Seiryu_the_Azure_Serpent.png/640px-Seiryu_the_Azure_Serpent.png"},{"name":"Arch-Glacor","rarity":"epic","id":"arch-glacor","subtitle":"Bosses","details":"An immense glacor on the Senntisten front whose arms, frost cannon and pillars teach many combat mechanics.","image":"https://runescape.wiki/images/thumb/Arch-Glacor.png/640px-Arch-Glacor.png"},{"name":"Croesus","rarity":"epic","id":"croesus","subtitle":"Bosses","details":"A fungal giant spreading rot through the Senntisten graveyard, subdued with gathering skills rather than weapons alone.","image":"https://runescape.wiki/images/thumb/Croesus.png/640px-Croesus.png"},{"name":"Yakamaru","rarity":"epic","id":"yakamaru","subtitle":"Bosses","details":"A great water beast of Mazcab faced after Beastmaster Durzag, using pools, jellies and stun roles in a raid team.","image":"https://runescape.wiki/images/thumb/Yakamaru.png/640px-Yakamaru.png"},{"name":"Nakatra, Devourer Eternal","rarity":"epic","id":"nakatra-devourer-eternal","subtitle":"Bosses","details":"Final guardian of the Sanctum of Rebirth, a Devourer wielding soul magic in patterns written across the arena floor.","image":"https://runescape.wiki/images/thumb/Nakatra%2C_Devourer_Eternal.png/640px-Nakatra%2C_Devourer_Eternal.png"},{"name":"Plague's End","rarity":"epic","id":"plague-s-end","subtitle":"Quests","details":"The elven civil war ends as the Dark Lord is confronted and Prifddinas, the lost city of the elves, is restored. Finale of the Elf quest series.","image":"https://runescape.wiki/images/thumb/Plague%27s_End.png/640px-Plague%27s_End.png?a08bc"},{"name":"River of Blood","rarity":"epic","id":"river-of-blood","subtitle":"Quests","details":"The final Myreque quest: the barrier of the River Salve fails, Castle Drakan's secrets surface, and the fate of Morytania is decided at last.","image":"https://runescape.wiki/images/thumb/River_of_Blood_Vampyre_army.png/640px-River_of_Blood_Vampyre_army.png?a122b"},{"name":"The Light Within","rarity":"epic","id":"the-light-within","subtitle":"Quests","details":"Gather the shards of Seren scattered across Gielinor and decide the shape of her return. A Grandmaster quest about the goddess of the elves.","image":"https://runescape.wiki/images/thumb/The_Light_Within.png/640px-The_Light_Within.png?2377b"},{"name":"Children of Mah","rarity":"epic","id":"children-of-mah","subtitle":"Quests","details":"The Mahjarrat return to Freneskae as their power fades, and Zaros confronts his sister's children. A quest of dying races and elder gods.","image":"https://runescape.wiki/images/thumb/Children_of_Mah.png/640px-Children_of_Mah.png?a54b0"},{"name":"Nomad's Elegy","rarity":"epic","id":"nomad-s-elegy","subtitle":"Quests","details":"Death, Icthlarin and the player invade Nomad's underworld fortress to stop him harvesting every soul in Gielinor. A quest of gods, souls and war.","image":"https://runescape.wiki/images/thumb/Nomad%27s_Elegy.png/640px-Nomad%27s_Elegy.png?9bae1"},{"name":"Curse of the Black Stone","rarity":"epic","id":"curse-of-the-black-stone","subtitle":"Quests","details":"Raid all three Elite Dungeons to break Xau-Tak's curse on the black stone, uniting the dragonkin, the Ambassador and the shadow reef storylines.","image":"https://runescape.wiki/images/thumb/Curse_of_the_Black_Stone.png/640px-Curse_of_the_Black_Stone.png?e1710"},{"name":"Azzanadra's Quest","rarity":"epic","id":"azzanadra-s-quest","subtitle":"Quests","details":"Azzanadra uncovers the buried city of Senntisten beneath Varrock and the Elder God eggs hidden below it, opening the Elder God Wars storyline.","image":"https://runescape.wiki/images/thumb/Azzanadra%27s_Quest.png/640px-Azzanadra%27s_Quest.png?dd7fe"},{"name":"Menaphos","rarity":"epic","id":"menaphos","subtitle":"Locations","details":"The golden city in the Kharidian Desert, split into four districts of workers, merchants, nobles and ports, ruled from a great pyramid.","image":"https://runescape.wiki/images/thumb/Menaphos.png/640px-Menaphos.png"},{"name":"Anachronia","rarity":"epic","id":"anachronia","subtitle":"Locations","details":"A prehistoric island north of Daemonheim, ruled by dinosaurs and the Dragonkin, with an agility course winding through jungle ruins.","image":"https://runescape.wiki/images/thumb/Anachronia.png/640px-Anachronia.png"},{"name":"Mazcab","rarity":"epic","id":"mazcab","subtitle":"Locations","details":"The homeworld of the goebies, a forested planet reached by world window, raided by Beastmaster Durzag and Yakamaru in Liberation raids.","image":"https://runescape.wiki/images/thumb/Mazcab.png/640px-Mazcab.png"},{"name":"Kethsi","rarity":"epic","id":"kethsi","subtitle":"Locations","details":"A ruined Dragonkin island world reached from Brimhaven, home to rune dragons, elite rune dragons and the murals of the Dragonkin past.","image":"https://runescape.wiki/images/thumb/Isle_of_Sann.png/640px-Isle_of_Sann.png"},{"name":"Daemonheim","rarity":"epic","id":"daemonheim","subtitle":"Locations","details":"A vast castle on a frozen peninsula east of the Wilderness, built over shifting dungeons delved in parties through Dungeoneering floors.","image":"https://runescape.wiki/images/thumb/Daemonheim_entrance.png/640px-Daemonheim_entrance.png"},{"name":"Zanaris","rarity":"epic","id":"zanaris","subtitle":"Locations","details":"The moon of Gielinor and home of the fairies, reached through fairy rings, with a market, wheat fields and the Cosmic Altar nearby.","image":"https://runescape.wiki/images/thumb/Updated_zanaris_aa.png/640px-Updated_zanaris_aa.png"},{"name":"Armadyl","rarity":"epic","id":"armadyl","subtitle":"Gods & NPCs","details":"God of justice and law, a winged avian deity who returned to Gielinor seeking a peaceful future for mortals and gods alike.","image":"https://runescape.wiki/images/thumb/Armadyl.png/640px-Armadyl.png"},{"name":"Bandos","rarity":"epic","id":"bandos","subtitle":"Gods & NPCs","details":"The Big High War God, a brutal deity of war who bred goblins, ogres and orks for battle and fell in a clash with Armadyl.","image":"https://runescape.wiki/images/thumb/Bandos.png/640px-Bandos.png"},{"name":"Azzanadra","rarity":"epic","id":"azzanadra","subtitle":"Gods & NPCs","details":"A loyal Mahjarrat champion of Zaros, imprisoned in a desert pyramid for ages and later restored to stand at his god's side.","image":"https://runescape.wiki/images/thumb/Azzanadra_ghost.png/640px-Azzanadra_ghost.png"},{"name":"Icthlarin","rarity":"epic","id":"icthlarin","subtitle":"Gods & NPCs","details":"Jackal-headed god of the dead who guides souls through the underworld and guards them against his sister Amascut's hunger.","image":"https://runescape.wiki/images/thumb/Icthlarin_%28Sliske%27s_Endgame%29.png/640px-Icthlarin_%28Sliske%27s_Endgame%29.png"},{"name":"Amascut","rarity":"epic","id":"amascut","subtitle":"Gods & NPCs","details":"The Devourer, a corrupted goddess of rebirth turned to destruction who seeks to consume the souls of the Kharidian dead.","image":"https://runescape.wiki/images/thumb/Amascut.png/640px-Amascut.png"},{"name":"Death","rarity":"epic","id":"death","subtitle":"Gods & NPCs","details":"Harold Death Esquire, the Grim Reaper of Gielinor, who collects the souls of the fallen and keeps his office beyond life.","image":"https://runescape.wiki/images/thumb/Death.png/640px-Death.png"},{"name":"Noxious Scythe","rarity":"epic","id":"noxious-scythe","subtitle":"Gear","details":"Tier 90 two-handed halberd made from Araxxi's fang and a spider leg, dropped whole in parts by Araxxor beneath Haunted Hill.","image":"https://runescape.wiki/images/thumb/Noxious_scythe_detail.png/512px-Noxious_scythe_detail.png"},{"name":"Noxious Longbow","rarity":"epic","id":"noxious-longbow","subtitle":"Gear","details":"Tier 90 two-handed bow made from Araxxi's eye and a spider leg from Araxxor, prized for its long range and heavy hits.","image":"https://runescape.wiki/images/thumb/Noxious_longbow_detail.png/512px-Noxious_longbow_detail.png"},{"name":"Noxious Staff","rarity":"epic","id":"noxious-staff","subtitle":"Gear","details":"Tier 90 two-handed staff made from Araxxi's web and a spider leg from Araxxor, a mainstay high-end Magic weapon for years.","image":"https://runescape.wiki/images/thumb/Noxious_staff_detail.png/512px-Noxious_staff_detail.png"},{"name":"Seismic Wand","rarity":"epic","id":"seismic-wand","subtitle":"Gear","details":"Tier 90 main-hand Magic weapon dropped by Vorago in his Borehole lair, paired by many players with the Seismic singularity.","image":"https://runescape.wiki/images/thumb/Seismic_wand_detail.png/512px-Seismic_wand_detail.png"},{"name":"Seismic Singularity","rarity":"epic","id":"seismic-singularity","subtitle":"Gear","details":"Tier 90 off-hand Magic orb dropped by Vorago, designed to pair with the Seismic wand for dual-wield spellcasting.","image":"https://runescape.wiki/images/thumb/Seismic_singularity_detail.png/512px-Seismic_singularity_detail.png"},{"name":"Blightbound Crossbow","rarity":"epic","id":"blightbound-crossbow","subtitle":"Gear","details":"Tier 92 main-hand crossbow dropped by Solak in the Lost Grove, firing bolts alongside its off-hand Blightbound partner.","image":"https://runescape.wiki/images/thumb/Blightbound_crossbow_detail.png/512px-Blightbound_crossbow_detail.png"},{"name":"Ascension Crossbow","rarity":"epic","id":"ascension-crossbow","subtitle":"Gear","details":"Tier 90 main-hand crossbow created from a dragon crossbow and Ascension fragments gathered in the Monastery of Ascension.","image":"https://runescape.wiki/images/thumb/Ascension_crossbow_detail.png/512px-Ascension_crossbow_detail.png"},{"name":"Masterwork Armour","rarity":"epic","id":"masterwork-armour","subtitle":"Gear","details":"Tier 90 melee armour smithed at 99 Smithing from glorious bars and masterwork components, the finest smithable plate in the game.","image":"https://runescape.wiki/images/thumb/Masterwork_melee_platebody_detail.png/512px-Masterwork_melee_platebody_detail.png"},{"name":"Cryptbloom Armour","rarity":"epic","id":"cryptbloom-armour","subtitle":"Gear","details":"Tier 90 Magic tank armour grown from Croesus in Senntisten, granting strong damage reduction when worn with earth spells.","image":"https://runescape.wiki/images/thumb/Cryptbloom_top_detail.png/512px-Cryptbloom_top_detail.png"},{"name":"Abyssal demon","rarity":"epic","id":"abyssal-demon","subtitle":"Monsters","details":"Abyssal demons are high-level Slayer monsters in the Slayer Tower and Abyssal Area, famed for dropping abyssal whips.","image":"https://runescape.wiki/images/thumb/Abyssal_demon.png/640px-Abyssal_demon.png"},{"name":"Dark beast","rarity":"epic","id":"dark-beast","subtitle":"Monsters","details":"Dark beasts are shadowy Slayer monsters found west of Lletya and in Mourner tunnels, known for dropping dark bows.","image":"https://runescape.wiki/images/thumb/Dark_beast.png/640px-Dark_beast.png"},{"name":"Frost dragon","rarity":"epic","id":"frost-dragon","subtitle":"Monsters","details":"Frost dragons are dragons in the Asgarnian Ice Dungeon resource area, prized for frost dragon bones worth much gold.","image":"https://runescape.wiki/images/thumb/Frost_dragon.png/640px-Frost_dragon.png"},{"name":"Rune dragon","rarity":"epic","id":"rune-dragon","subtitle":"Monsters","details":"Rune dragons are metal dragons on Mount Firewake on Kethsi, protected by armour that phases as the fight continues.","image":"https://runescape.wiki/images/thumb/Rune_dragon_%28armoured%29.png/640px-Rune_dragon_%28armoured%29.png"},{"name":"Santa Hat","rarity":"epic","id":"santa-hat","subtitle":"Items","details":"A red bobble hat dropped during a classic Christmas event, worn ever since as a cheerful marker of holiday-season wealth.","image":"https://runescape.wiki/images/Santa_hat_detail.png"},{"name":"White Partyhat","rarity":"epic","id":"white-partyhat","subtitle":"Items","details":"A white paper partyhat from the earliest Christmas crackers, a clean and simple crown with an enormous price tag.","image":"https://runescape.wiki/images/White_partyhat_detail.png"},{"name":"Disk of Returning","rarity":"epic","id":"disk-of-returning","subtitle":"Items","details":"A discontinued black disk once used to whisk its owner to safety, now kept purely as a rare collector's treasure.","image":"https://runescape.wiki/images/thumb/Disk_of_returning_detail.png/640px-Disk_of_returning_detail.png"},{"name":"Dominion Tower","rarity":"epic","id":"dominion-tower","subtitle":"Activities","details":"A desert tower of boss rematches, where adventurers refight quest foes in endurance, climber and special modes.","image":"https://runescape.wiki/images/thumb/Dominion_exterior.png/640px-Dominion_exterior.png"},{"name":"Liberation of Mazcab","rarity":"epic","id":"liberation-of-mazcab","subtitle":"Activities","details":"A group raid on Mazcab where teams of ten battle Beastmaster Durzag and the water beast Yakamaru for Teci rewards.","image":"https://runescape.wiki/images/thumb/Liberation_of_Mazcab_Entrance.png/640px-Liberation_of_Mazcab_Entrance.png"},{"name":"Shattered Worlds","rarity":"epic","id":"shattered-worlds","subtitle":"Activities","details":"Shattered pocket worlds spilling abyssal energy, where adventurers fight through endless portals of monsters for anima and abilities.","image":"https://runescape.wiki/images/thumb/Shattered_Worlds.png/640px-Shattered_Worlds.png?b29f2"},{"name":"Prayer","rarity":"rare","id":"prayer","subtitle":"Skills","details":"Holy blessings earned by burying bones and offering remains at altars, boosting combat, protecting items, and resisting damage.","image":"https://runescape.wiki/images/thumb/Prayer_cape_detail.png/640px-Prayer_cape_detail.png"},{"name":"Magic","rarity":"rare","id":"magic","subtitle":"Skills","details":"Casting battle, teleport, alchemy, and enchantment spells from runes, staves, and spellbooks drawn from several ancient traditions.","image":"https://runescape.wiki/images/thumb/Magic_cape_detail.png/640px-Magic_cape_detail.png"},{"name":"Herblore","rarity":"rare","id":"herblore","subtitle":"Skills","details":"Cleaning grimy herbs and brewing them into potions, from simple attack boosts to the overloads that define high-level combat.","image":"https://runescape.wiki/images/thumb/Herblore_cape_detail.png/640px-Herblore_cape_detail.png"},{"name":"Slayer","rarity":"rare","id":"slayer","subtitle":"Skills","details":"Receiving assignments from Slayer masters to kill specific monsters, many of which drop unique gear found nowhere else.","image":"https://runescape.wiki/images/thumb/Slayer_cape_detail.png/640px-Slayer_cape_detail.png"},{"name":"Divination","rarity":"rare","id":"divination","subtitle":"Skills","details":"Harvesting energy and memories from wisps at colonies across the world, weaving them into portents, signs, and useful items.","image":"https://runescape.wiki/images/thumb/Divination_cape_detail.png/640px-Divination_cape_detail.png"},{"name":"General Graardor","rarity":"rare","id":"general-graardor","subtitle":"Bosses","details":"Bandos's ogre general in the God Wars Dungeon, pounding intruders with crushing melee and bodyguards at his side.","image":"https://runescape.wiki/images/thumb/General_Graardor.png/640px-General_Graardor.png"},{"name":"Kree'arra","rarity":"rare","id":"kree-arra","subtitle":"Bosses","details":"Armadyl's aviansie commander in the God Wars Dungeon, battering foes with ranged storms from the air.","image":"https://runescape.wiki/images/thumb/Kree%27arra.png/640px-Kree%27arra.png"},{"name":"Commander Zilyana","rarity":"rare","id":"commander-zilyana","subtitle":"Bosses","details":"Saradomin's icyene commander in the God Wars Dungeon, striking swiftly with lightning and Saradominist zeal.","image":"https://runescape.wiki/images/Commander_Zilyana.png"},{"name":"K'ril Tsutsaroth","rarity":"rare","id":"k-ril-tsutsaroth","subtitle":"Bosses","details":"Zamorak's demon general in the God Wars Dungeon, poisoning and smashing enemies with infernal strength.","image":"https://runescape.wiki/images/thumb/K%27ril_Tsutsaroth.png/640px-K%27ril_Tsutsaroth.png"},{"name":"Vindicta","rarity":"rare","id":"vindicta","subtitle":"Bosses","details":"An Ilujanka dragon rider raised by Gorvek, fighting for Zaros in the Heart of Gielinor on dragonback.","image":"https://runescape.wiki/images/Vindicta.png"},{"name":"Helwyr","rarity":"rare","id":"helwyr","subtitle":"Bosses","details":"A Cywir elf shapeshifter serving Seren in the Heart of Gielinor, fighting as a wolf among mushrooms and vines.","image":"https://runescape.wiki/images/thumb/Helwyr.png/512px-Helwyr.png"},{"name":"Gregorovic","rarity":"rare","id":"gregorovic","subtitle":"Bosses","details":"A masked, plague-ridden servant of Sliske in the Heart of Gielinor, swapping places with spirits and shadows.","image":"https://runescape.wiki/images/thumb/Gregorovic.png/640px-Gregorovic.png"},{"name":"Twin Furies","rarity":"rare","id":"twin-furies","subtitle":"Bosses","details":"Avaryss and Nymora, Zamorak's twin demon assassins in the Heart of Gielinor, charging and raining blades together.","image":"https://runescape.wiki/images/Nymora%2C_the_Vengeful.png"},{"name":"Black Stone Dragon","rarity":"rare","id":"black-stone-dragon","subtitle":"Bosses","details":"A dragon wrought from black stone in Dragonkin Laboratory, breathing gemstone fire over its hoard and vault.","image":"https://runescape.wiki/images/thumb/Black_stone_dragon.png/640px-Black_stone_dragon.png"},{"name":"Beastmaster Durzag","rarity":"rare","id":"beastmaster-durzag","subtitle":"Bosses","details":"A goebie beastmaster raiding Mazcab with his pets Tuz and Krar, fought before the water beast Yakamaru.","image":"https://runescape.wiki/images/thumb/Beastmaster_Durzag.png/640px-Beastmaster_Durzag.png"},{"name":"Rise of the Six","rarity":"rare","id":"rise-of-the-six","subtitle":"Bosses","details":"The six original Barrows brothers empowered by Sliske, fought all at once on spinning platforms in the Shadow Realm.","image":"https://runescape.wiki/images/thumb/Barrows_Rise_of_the_Six_banner.jpg/640px-Barrows_Rise_of_the_Six_banner.jpg"},{"name":"Amascut, the Devourer","rarity":"rare","id":"amascut-the-devourer","subtitle":"Bosses","details":"The goddess of destruction corrupting the Sanctum and the souls of the dead, faced in her own devouring form.","image":"https://runescape.wiki/images/Amascut%2C_the_Devourer.png"},{"name":"Zemouregal & Vorkath","rarity":"rare","id":"zemouregal-vorkath","subtitle":"Bosses","details":"A Mahjarrat necromancer and his undead dragon at Fort Forinthry, raising skeletons across the battlefield.","image":"https://runescape.wiki/images/thumb/Vorkath.png/640px-Vorkath.png"},{"name":"Kezalam, the Wanderer","rarity":"rare","id":"kezalam-the-wanderer","subtitle":"Bosses","details":"A moonstone golem wandering the Sanctum of Rebirth, smashing the arena with boulders and soul magic.","image":"https://runescape.wiki/images/thumb/Kezalam%2C_the_Wanderer.png/640px-Kezalam%2C_the_Wanderer.png"},{"name":"Vermyx, Brood Mother","rarity":"rare","id":"vermyx-brood-mother","subtitle":"Bosses","details":"A brood mother lamia guarding the Sanctum of Rebirth, calling her broodlings while striking from her coils.","image":"https://runescape.wiki/images/thumb/Vermyx%2C_Brood_Mother.png/640px-Vermyx%2C_Brood_Mother.png"},{"name":"Recipe for Disaster","rarity":"rare","id":"recipe-for-disaster","subtitle":"Quests","details":"Free the Lumbridge Secret Council from the Culinaromancer by cooking their favourite dishes and defeating the foes tied to each course.","image":"https://runescape.wiki/images/thumb/Recipe_for_Disaster.png/640px-Recipe_for_Disaster.png?f6803"},{"name":"Dragon Slayer","rarity":"rare","id":"dragon-slayer","subtitle":"Quests","details":"Prove worthy to face Elvarg on Crandor, buy a ship, repair it, and slay the green dragon that destroyed the island settlement.","image":"https://runescape.wiki/images/thumb/Dragon_Slayer.png/640px-Dragon_Slayer.png?78056"},{"name":"The Chosen Commander","rarity":"rare","id":"the-chosen-commander","subtitle":"Quests","details":"Help Zanik and the Dorgeshuun when a H.A.M. plot and a Bandos avatar threaten their cave city and its hard-won place on the surface.","image":"https://runescape.wiki/images/thumb/The_Chosen_Commander.png/640px-The_Chosen_Commander.png?6624d"},{"name":"One Small Favour","rarity":"rare","id":"one-small-favour","subtitle":"Quests","details":"A simple errand in Shilo Village spirals into a chain of favours across Gielinor, as every person helped asks for one more thing first.","image":"https://runescape.wiki/images/thumb/One_Small_Favour.png/640px-One_Small_Favour.png?aabf1"},{"name":"The Fremennik Trials","rarity":"rare","id":"the-fremennik-trials","subtitle":"Quests","details":"Earn a place among the Fremennik of Rellekka by passing trials of skill, wit and combat set by the council and its rival candidates.","image":"https://runescape.wiki/images/thumb/The_Fremennik_Trials.png/640px-The_Fremennik_Trials.png?92888"},{"name":"Shilo Village","rarity":"rare","id":"shilo-village","subtitle":"Quests","details":"Find the missing Rashiliyia tomb in the Kharazi Jungle, face undead horrors, and lift the curse hanging over Shilo Village.","image":"https://runescape.wiki/images/thumb/Shilo_Village.png/640px-Shilo_Village.png?6e68d"},{"name":"Underground Pass","rarity":"rare","id":"underground-pass","subtitle":"Quests","details":"Cross Iban's corrupted Underground Pass west of Ardougne, surviving traps, disciples and the whispers that test every traveller.","image":"https://runescape.wiki/images/thumb/Underground_Pass.png/640px-Underground_Pass.png?53440"},{"name":"Regicide","rarity":"rare","id":"regicide","subtitle":"Quests","details":"After King Lathas is exposed, help the elves of Tirannwn, cross the mountain pass, and face a plot that ends with a king's death.","image":"https://runescape.wiki/images/thumb/Regicide.png/640px-Regicide.png?6e94f"},{"name":"The Dig Site","rarity":"rare","id":"the-dig-site","subtitle":"Quests","details":"Pass archaeology exams at the Varrock dig site, uncover an ancient altar below, and stop a ritual tied to a forgotten god.","image":"https://runescape.wiki/images/thumb/The_Dig_Site.png/640px-The_Dig_Site.png?67952"},{"name":"Heroes' Quest","rarity":"rare","id":"heroes-quest","subtitle":"Quests","details":"Gather a fire feather, a master thief's armband and a cooked lava eel to earn entry to the Heroes' Guild north of Taverley.","image":"https://runescape.wiki/images/thumb/Heroes%27Quest.png/640px-Heroes%27Quest.png?3441e"},{"name":"Family Crest","rarity":"rare","id":"family-crest","subtitle":"Quests","details":"Recover the scattered pieces of the Fitzharmon family crest from three brothers and a demon holding the final fragment.","image":"https://runescape.wiki/images/thumb/Family_Crest.png/640px-Family_Crest.png?ef685"},{"name":"Clock Tower","rarity":"rare","id":"clock-tower","subtitle":"Quests","details":"Help Brother Kojo repair the Ardougne Clock Tower by finding its four coloured cogs hidden in the dungeons below the tower.","image":"https://runescape.wiki/images/thumb/Clock_Tower.png/640px-Clock_Tower.png?50f73"},{"name":"Grand Exchange","rarity":"rare","id":"grand-exchange","subtitle":"Locations","details":"The great marketplace north-west of Varrock, where players trade through clerks around a central fountain in Gielinor's busiest hub.","image":"https://runescape.wiki/images/thumb/Grand_Exchange_%28Varrock%29.png/640px-Grand_Exchange_%28Varrock%29.png"},{"name":"God Wars Dungeon","rarity":"rare","id":"god-wars-dungeon","subtitle":"Locations","details":"A frozen cavern north of Trollheim where armies of Zamorak, Saradomin, Bandos and Armadyl still fight over the godsword in icy halls.","image":"https://runescape.wiki/images/thumb/God_Wars_Dungeon_temple.png/640px-God_Wars_Dungeon_temple.png"},{"name":"Heart of Gielinor","rarity":"rare","id":"heart-of-gielinor","subtitle":"Locations","details":"A dungeon in the Kharidian Desert where Seren, Zamorak, Zaros and Sliske armies clash, also called the Heart and home to four generals.","image":"https://runescape.wiki/images/thumb/Heart_of_Gielinor.png/640px-Heart_of_Gielinor.png"},{"name":"Tirannwn","rarity":"rare","id":"tirannwn","subtitle":"Locations","details":"The elven lands in the far west, a dense forest region of traps, mushrooms and crystal, home to Isafdar, Lletya and Prifddinas.","image":"https://runescape.wiki/images/thumb/Isafdar_Forest.png/640px-Isafdar_Forest.png"},{"name":"The Wilderness","rarity":"rare","id":"the-wilderness","subtitle":"Locations","details":"A vast, dangerous wasteland covering the north of the mainland, scarred by the God Wars, with volcanoes, ruins and open PvP risk.","image":"https://runescape.wiki/images/thumb/Wilderness.png/640px-Wilderness.png"},{"name":"Keldagrim","rarity":"rare","id":"keldagrim","subtitle":"Locations","details":"The underground capital of the dwarves, split by the River Kelda, reached by mine cart, with blast furnaces, markets and a grand palace.","image":"https://runescape.wiki/images/thumb/Keldagrim_East.png/640px-Keldagrim_East.png"},{"name":"Fort Forinthry","rarity":"rare","id":"fort-forinthry","subtitle":"Locations","details":"A player-built fort on the edge of the Wilderness north of Varrock, with a workshop, town hall, kitchen and command centre to upgrade.","image":"https://runescape.wiki/images/thumb/Fort_Forinthry.png/640px-Fort_Forinthry.png"},{"name":"Piscatoris","rarity":"rare","id":"piscatoris","subtitle":"Locations","details":"A fishing colony on the north-west coast, netting monkfish in the sea below, reached after Swan Song and linked by fairy ring and boat.","image":"https://runescape.wiki/images/thumb/Piscatoris_Fishing_Colony.png/640px-Piscatoris_Fishing_Colony.png"},{"name":"Darkmeyer","rarity":"rare","id":"darkmeyer","subtitle":"Locations","details":"The vampyre capital in Morytania, a walled city of vyres and blood drinkers, with the Blisterwood Tree and Daeyalt essence at its heart.","image":"https://runescape.wiki/images/thumb/Darkmeyer_NXT.png/640px-Darkmeyer_NXT.png"},{"name":"The Lost Grove","rarity":"rare","id":"the-lost-grove","subtitle":"Locations","details":"A hidden grove south of the Poison Waste, filled with vinecrawlers and lampenflora, and home to Solak, the Guardian of the Grove.","image":"https://runescape.wiki/images/thumb/The_Lost_Grove.png/640px-The_Lost_Grove.png"},{"name":"Ful","rarity":"rare","id":"ful","subtitle":"Gods & NPCs","details":"Elder God of fire and constancy, a vast volcanic creator whose TokHaar were made to build and perfect the worlds.","image":"https://runescape.wiki/images/thumb/Ful_awakens.png/640px-Ful_awakens.png"},{"name":"Wen","rarity":"rare","id":"wen","subtitle":"Gods & NPCs","details":"Elder God of ice and reversal, a colossal frozen creator resting beneath Ice Mountain in the shape of a great mountain.","image":"https://runescape.wiki/images/thumb/Wen.png/640px-Wen.png"},{"name":"Bik","rarity":"rare","id":"bik","subtitle":"Gods & NPCs","details":"Elder God of earth and alteration, a plant-like creator whose spores and roots spread across the jungles of Gielinor.","image":"https://runescape.wiki/images/thumb/Bik.png/640px-Bik.png"},{"name":"Tumeken","rarity":"rare","id":"tumeken","subtitle":"Gods & NPCs","details":"God of the sun and light, ruler of the Menaphite pantheon whose sacrifice in the desert war left his aspects scattered.","image":"https://runescape.wiki/images/thumb/Tumeken.png/640px-Tumeken.png"},{"name":"Elidinis","rarity":"rare","id":"elidinis","subtitle":"Gods & NPCs","details":"Goddess of fertility and growth, wife of Tumeken and river goddess of the Elid, revered across the Kharidian desert.","image":"https://runescape.wiki/images/thumb/Elidinis_concept_art.png/640px-Elidinis_concept_art.png"},{"name":"Marimbo","rarity":"rare","id":"marimbo","subtitle":"Gods & NPCs","details":"Gorilla goddess of hedonism and revelry, winner of a thumb-wrestling contest for divinity and patron of Ape Atoll's apes.","image":"https://runescape.wiki/images/thumb/Marimbo_%28holding%29.png/640px-Marimbo_%28holding%29.png"},{"name":"Brassica Prime","rarity":"rare","id":"brassica-prime","subtitle":"Gods & NPCs","details":"The cabbage god, a divine vegetable worshipped by cabbages and goblins alike, who preaches the tasty enlightenment of greens.","image":"https://runescape.wiki/images/thumb/Brassica_Prime.png/640px-Brassica_Prime.png"},{"name":"War","rarity":"rare","id":"war","subtitle":"Gods & NPCs","details":"A retired horseman who runs War's Retreat above Death's office, rewarding adventurers who prove themselves against bosses.","image":"https://runescape.wiki/images/thumb/War.png/640px-War.png"},{"name":"Wise Old Man","rarity":"rare","id":"wise-old-man","subtitle":"Gods & NPCs","details":"Dionysius, the famed retired adventurer of Draynor Village, robber of its bank and keeper of quest capes and old tales.","image":"https://runescape.wiki/images/thumb/Wise_Old_Man.png/640px-Wise_Old_Man.png"},{"name":"Drygore Longsword","rarity":"rare","id":"drygore-longsword","subtitle":"Gear","details":"Tier 90 main-hand melee weapon dropped by the Kalphite King in the Exiled Kalphite Hive, one of the three original Drygores.","image":"https://runescape.wiki/images/thumb/Drygore_longsword_detail.png/512px-Drygore_longsword_detail.png"},{"name":"Drygore Mace","rarity":"rare","id":"drygore-mace","subtitle":"Gear","details":"Tier 90 main-hand melee weapon dropped by the Kalphite King, notable for its prayer bonus among the Drygore weapon set.","image":"https://runescape.wiki/images/thumb/Drygore_mace_detail.png/512px-Drygore_mace_detail.png"},{"name":"Drygore Rapier","rarity":"rare","id":"drygore-rapier","subtitle":"Gear","details":"Tier 90 main-hand melee weapon dropped by the Kalphite King in the Exiled Kalphite Hive, built for fast, accurate stabbing.","image":"https://runescape.wiki/images/thumb/Drygore_rapier_detail.png/512px-Drygore_rapier_detail.png"},{"name":"Saradomin Godsword","rarity":"rare","id":"saradomin-godsword","subtitle":"Gear","details":"Tier 75 two-handed sword made by attaching a Saradomin hilt to a godsword blade from Commander Zilyana in the God Wars Dungeon.","image":"https://runescape.wiki/images/thumb/Saradomin_godsword_detail.png/512px-Saradomin_godsword_detail.png"},{"name":"Armadyl Godsword","rarity":"rare","id":"armadyl-godsword","subtitle":"Gear","details":"Tier 75 two-handed sword made with an Armadyl hilt from Kree'arra in the God Wars Dungeon, famed for its huge special attack.","image":"https://runescape.wiki/images/thumb/Armadyl_godsword_detail.png/512px-Armadyl_godsword_detail.png"},{"name":"Bandos Godsword","rarity":"rare","id":"bandos-godsword","subtitle":"Gear","details":"Tier 75 two-handed sword made with a Bandos hilt from General Graardor in the God Wars Dungeon, able to drain Defence levels.","image":"https://runescape.wiki/images/thumb/Bandos_godsword_detail.png/512px-Bandos_godsword_detail.png"},{"name":"Zamorak Godsword","rarity":"rare","id":"zamorak-godsword","subtitle":"Gear","details":"Tier 75 two-handed sword made with a Zamorak hilt from K'ril Tsutsaroth in the God Wars Dungeon, freezing foes with ice.","image":"https://runescape.wiki/images/thumb/Zamorak_godsword_detail.png/400px-Zamorak_godsword_detail.png"},{"name":"Tectonic Armour","rarity":"rare","id":"tectonic-armour","subtitle":"Gear","details":"Tier 90 Magic power armour made from tectonic energy dropped by Vorago and stones of binding, among the strongest robes made.","image":"https://runescape.wiki/images/thumb/Tectonic_robe_top_detail.png/512px-Tectonic_robe_top_detail.png"},{"name":"Sirenic Armour","rarity":"rare","id":"sirenic-armour","subtitle":"Gear","details":"Tier 90 Ranged power armour made from sirenic scales dropped across the world and algarum thread bought in Ooglog.","image":"https://runescape.wiki/images/thumb/Sirenic_hauberk_detail.png/512px-Sirenic_hauberk_detail.png"},{"name":"Vestments of Havoc","rarity":"rare","id":"vestments-of-havoc","subtitle":"Gear","details":"Tier 95 Magic power robes dropped by Zamorak, Lord of Chaos in Senntisten, boosting critical damage while channelling.","image":"https://runescape.wiki/images/thumb/Vestments_of_havoc_robe_top_detail.png/512px-Vestments_of_havoc_robe_top_detail.png"},{"name":"Torva Armour","rarity":"rare","id":"torva-armour","subtitle":"Gear","details":"Tier 80 melee power armour dropped by Nex in the Ancient Prison beneath the God Wars Dungeon, boosting maximum lifepoints.","image":"https://runescape.wiki/images/thumb/Torva_platebody_detail.png/512px-Torva_platebody_detail.png"},{"name":"Pernix Armour","rarity":"rare","id":"pernix-armour","subtitle":"Gear","details":"Tier 80 Ranged power armour dropped by Nex in the Ancient Prison, named for a swift and deadly Zaryte guardian of Zaros.","image":"https://runescape.wiki/images/thumb/Pernix_body_detail.png/512px-Pernix_body_detail.png"},{"name":"Virtus Armour","rarity":"rare","id":"virtus-armour","subtitle":"Gear","details":"Tier 80 Magic power armour dropped by Nex in the Ancient Prison beneath the God Wars Dungeon, boosting maximum lifepoints.","image":"https://runescape.wiki/images/thumb/Virtus_robe_top_detail.png/512px-Virtus_robe_top_detail.png"},{"name":"Malevolent Armour","rarity":"rare","id":"malevolent-armour","subtitle":"Gear","details":"Tier 90 melee power armour made from malevolent energy and reinforcing plates dropped by the Barrows brothers' wight.","image":"https://runescape.wiki/images/thumb/Malevolent_cuirass_detail.png/512px-Malevolent_cuirass_detail.png"},{"name":"Nechryael","rarity":"rare","id":"nechryael","subtitle":"Monsters","details":"Nechryael are demonic Slayer monsters in the Slayer Tower and Chaos Tunnels, summoning death spawns to aid them in combat.","image":"https://runescape.wiki/images/thumb/Nechryael.png/640px-Nechryael.png"},{"name":"Gargoyle","rarity":"rare","id":"gargoyle","subtitle":"Monsters","details":"Gargoyles are winged stone Slayer monsters in the Slayer Tower, finished off with a rock hammer when their health is low.","image":"https://runescape.wiki/images/thumb/Gargoyle.png/640px-Gargoyle.png"},{"name":"Lava strykewyrm","rarity":"rare","id":"lava-strykewyrm","subtitle":"Monsters","details":"Lava strykewyrms burrow beneath the Lava Maze in the Wilderness, erupting from lava pools to attack passing adventurers.","image":"https://runescape.wiki/images/thumb/Lava_strykewyrm.png/640px-Lava_strykewyrm.png"},{"name":"Adamant dragon","rarity":"rare","id":"adamant-dragon","subtitle":"Monsters","details":"Adamant dragons are metal dragons in the Brimhaven Dungeon and Dragonkin Laboratory, breathing dragonfire at range.","image":"https://runescape.wiki/images/thumb/Adamant_dragon.png/640px-Adamant_dragon.png"},{"name":"Celestial dragon","rarity":"rare","id":"celestial-dragon","subtitle":"Monsters","details":"Celestial dragons are dragons on Dragontooth Island that can briefly stop time around them with a powerful breath attack.","image":"https://runescape.wiki/images/thumb/Celestial_dragon.png/640px-Celestial_dragon.png"},{"name":"Muspah","rarity":"rare","id":"muspah","subtitle":"Monsters","details":"Muspah are shapeshifting creatures from Freneskae that change between melee, ranged and magic forms during combat.","image":"https://runescape.wiki/images/thumb/Throwing_muspah.png/640px-Throwing_muspah.png"},{"name":"Ripper demon","rarity":"rare","id":"ripper-demon","subtitle":"Monsters","details":"Ripper demons are possessed miners in a mine east of Al Kharid, leaping onto victims and growing deadlier when wounded.","image":"https://runescape.wiki/images/thumb/Ripper_demon.png/640px-Ripper_demon.png"},{"name":"Purple Partyhat","rarity":"rare","id":"purple-partyhat","subtitle":"Items","details":"A purple paper partyhat pulled from a Christmas cracker long ago, one of six original colours that were never released again.","image":"https://runescape.wiki/images/Purple_partyhat_detail.png"},{"name":"Half Full Wine Jug","rarity":"rare","id":"half-full-wine-jug","subtitle":"Items","details":"Created when a player drank half a jug of wine before wine drinking changed: a discontinued accident of everyday history.","image":"https://runescape.wiki/images/thumb/Half_full_wine_jug_detail.png/640px-Half_full_wine_jug_detail.png"},{"name":"Red Hallowe'en Mask","rarity":"rare","id":"red-hallowe-en-mask","subtitle":"Items","details":"A red mask dropped only on 31 October 2002. Its examine says it all: Aaaarrrghhh... I'm a monster. Boo!","image":"https://runescape.wiki/images/Red_hallowe%27en_mask_detail.png"},{"name":"Third Age Dye","rarity":"rare","id":"third-age-dye","subtitle":"Items","details":"A dye from elite Treasure Trails that recolours high-level gear in the pale white and grey of the Third Age.","image":"https://runescape.wiki/images/thumb/Third_Age_dye_detail.png/640px-Third_Age_dye_detail.png"},{"name":"Blood Dye","rarity":"rare","id":"blood-dye","subtitle":"Items","details":"A dye from elite Treasure Trails that recolours high-level weapons and armour in deep crimson, consumed when applied.","image":"https://runescape.wiki/images/Blood_dye_detail.png"},{"name":"Pest Control","rarity":"rare","id":"pest-control","subtitle":"Activities","details":"A cooperative defence of a Void Knight on an outpost island, holding portals against waves of shifting pests.","image":"https://runescape.wiki/images/thumb/Pest_Control_gameplay.png/640px-Pest_Control_gameplay.png"},{"name":"Soul Wars","rarity":"rare","id":"soul-wars","subtitle":"Activities","details":"A team battle over the Soul Obelisk, where players slay foes, bury bones and feed soul fragments to weaken avatars.","image":"https://runescape.wiki/images/thumb/Soul_Wars.png/640px-Soul_Wars.png"},{"name":"Barbarian Assault","rarity":"rare","id":"barbarian-assault","subtitle":"Activities","details":"A team arena beneath the Barbarian Outpost where squads in set roles defeat waves of penance creatures and queens.","image":"https://runescape.wiki/images/thumb/Barbarian_Assault.png/640px-Barbarian_Assault.png"},{"name":"Fight Kiln","rarity":"rare","id":"fight-kiln","subtitle":"Activities","details":"A solo endurance trial in the TzHaar city, fighting waves in a kiln to earn a fire cape upgrade called the TokHaar-Kal.","image":"https://runescape.wiki/images/thumb/Elder_Kiln.png/640px-Elder_Kiln.png"},{"name":"Pyramid Plunder","rarity":"rare","id":"pyramid-plunder","subtitle":"Activities","details":"A tomb-raiding activity inside Jalsavrah in Sophanem, looting urns and sarcophagi against a rising mummy's curse.","image":"https://runescape.wiki/images/thumb/Pyramid_plunder.png/640px-Pyramid_plunder.png"},{"name":"Attack","rarity":"uncommon","id":"attack","subtitle":"Skills","details":"Accuracy with melee weapons rises with this level, unlocking stronger gear and special attacks for close-quarters combat.","image":"https://runescape.wiki/images/thumb/Attack_cape_detail.png/640px-Attack_cape_detail.png"},{"name":"Ranged","rarity":"uncommon","id":"ranged","subtitle":"Skills","details":"The art of bows, crossbows, and thrown weapons, striking enemies from a safe distance with arrows, bolts, and chinchompas.","image":"https://runescape.wiki/images/thumb/Ranged_cape_detail.png/640px-Ranged_cape_detail.png"},{"name":"Runecrafting","rarity":"uncommon","id":"runecrafting","subtitle":"Skills","details":"Imbuing essence at mysterious altars to create the runes that fuel magic, via the Abyss, the altars, and the Runespan itself.","image":"https://runescape.wiki/images/thumb/Runecrafting_cape_detail.png/640px-Runecrafting_cape_detail.png"},{"name":"Mining","rarity":"uncommon","id":"mining","subtitle":"Skills","details":"Swinging a pickaxe at rocks across the world to gather ore, gems, and essence, feeding furnaces and the Smithing trade.","image":"https://runescape.wiki/images/thumb/Mining_cape_detail.png/640px-Mining_cape_detail.png"},{"name":"Smithing","rarity":"uncommon","id":"smithing","subtitle":"Skills","details":"Smelting ore into bars and hammering them into weapons and armour, from bronze basics to masterwork equipment for combat.","image":"https://runescape.wiki/images/thumb/Smithing_cape_detail.png/640px-Smithing_cape_detail.png"},{"name":"Farming","rarity":"uncommon","id":"farming","subtitle":"Skills","details":"Planting seeds in patches worldwide and returning to harvest herbs, trees, and produce, while raising animals on the farm.","image":"https://runescape.wiki/images/thumb/Farming_cape_detail.png/640px-Farming_cape_detail.png"},{"name":"Construction","rarity":"uncommon","id":"construction","subtitle":"Skills","details":"Building a player-owned house room by room, adding altars, portals, workshops, and furniture that serve daily training.","image":"https://runescape.wiki/images/thumb/Construction_cape_detail.png/640px-Construction_cape_detail.png"},{"name":"Hunter","rarity":"uncommon","id":"hunter","subtitle":"Skills","details":"Tracking, trapping, and snaring creatures from kebbits to implings, using their hides, bones, and loot for profit and training.","image":"https://runescape.wiki/images/Hunter_cape_detail.png"},{"name":"King Black Dragon","rarity":"uncommon","id":"king-black-dragon","subtitle":"Bosses","details":"The three-headed black dragon in his Wilderness lair, an early boss whose breath spans fire, poison and frost.","image":"https://runescape.wiki/images/thumb/King_Black_Dragon.png/640px-King_Black_Dragon.png"},{"name":"Kalphite Queen","rarity":"uncommon","id":"kalphite-queen","subtitle":"Bosses","details":"Insectoid queen beneath the Kharidian Desert who changes form mid-fight, swapping exoskeleton for wings.","image":"https://runescape.wiki/images/thumb/Kalphite_Queen.png/640px-Kalphite_Queen.png"},{"name":"Chaos Elemental","rarity":"uncommon","id":"chaos-elemental","subtitle":"Bosses","details":"A swirling mass of chaos in the deep Wilderness that teleports, disarms and un-equips unwary fighters.","image":"https://runescape.wiki/images/thumb/Chaos_Elemental.png/640px-Chaos_Elemental.png"},{"name":"TzTok-Jad","rarity":"uncommon","id":"tztok-jad","subtitle":"Bosses","details":"The lava giant at the end of the TzHaar Fight Cave, whose healers and changing attacks test calm prayer switching.","image":"https://runescape.wiki/images/thumb/TzTok-Jad.png/640px-TzTok-Jad.png"},{"name":"Har-Aken","rarity":"uncommon","id":"har-aken","subtitle":"Bosses","details":"A many-tentacled lava monster met in the Fight Kiln, surfacing between waves of TokHaar to spit fire.","image":"https://runescape.wiki/images/thumb/Har-Aken.png/640px-Har-Aken.png"},{"name":"Masuta the Ascended","rarity":"uncommon","id":"masuta-the-ascended","subtitle":"Bosses","details":"An Aminishi acolyte ascended by Seiryu's scales, spinning his warspear through the Temple of Aminishi.","image":"https://runescape.wiki/images/thumb/Masuta_the_Ascended.png/640px-Masuta_the_Ascended.png"},{"name":"Taraket the Necromancer","rarity":"uncommon","id":"taraket-the-necromancer","subtitle":"Bosses","details":"A necromancer in the Shadow Reef who raises corpses, rifts and the slain Crassian Leviathan to his aid.","image":"https://runescape.wiki/images/Taraket_the_Necromancer.png"},{"name":"The Magister","rarity":"uncommon","id":"the-magister","subtitle":"Bosses","details":"Oreb, the Magister of House Charron, a Teragard necromancer fought alone in the Sophanem Slayer Dungeon.","image":"https://runescape.wiki/images/thumb/The_Magister.png/640px-The_Magister.png"},{"name":"Legiones","rarity":"uncommon","id":"legiones","subtitle":"Bosses","details":"Six ascended legions in the Monastery of Ascension, each unlocked by a keystone and guarding crossbow parts.","image":"https://runescape.wiki/images/Legio_Primus.png"},{"name":"Dagannoth Kings","rarity":"uncommon","id":"dagannoth-kings","subtitle":"Bosses","details":"Three dagannoth rulers beneath Waterbirth Island, each strong in one combat style and weak to another.","image":"https://runescape.wiki/images/thumb/Dagannoth_Kings.png/640px-Dagannoth_Kings.png"},{"name":"Rex Matriarchs","rarity":"uncommon","id":"rex-matriarchs","subtitle":"Bosses","details":"Ancient female rexes on Anachronia, each matriarch mastering a different style of combat, venom and power.","image":"https://runescape.wiki/images/thumb/Orikalka.png/640px-Orikalka.png"},{"name":"Hermod, the Spirit of War","rarity":"uncommon","id":"hermod-the-spirit-of-war","subtitle":"Bosses","details":"Rasial's phantom bodyguard at his citadel above the City of Um, who summons armoured phantoms in battle.","image":"https://runescape.wiki/images/thumb/Hermod%2C_the_Spirit_of_War.png/640px-Hermod%2C_the_Spirit_of_War.png"},{"name":"Osseous","rarity":"uncommon","id":"osseous","subtitle":"Bosses","details":"A skeletal rex matriarch raised on Anachronia, bringing necrotic power to the Rex Matriarchs' hunting grounds.","image":"https://runescape.wiki/images/thumb/Osseous.png/640px-Osseous.png"},{"name":"Astellarn, the First Celestial","rarity":"uncommon","id":"astellarn-the-first-celestial","subtitle":"Bosses","details":"The first celestial dragon created in Dragonkin Laboratory, shifting colours to change its resistances.","image":"https://runescape.wiki/images/thumb/Astellarn.png/640px-Astellarn.png"},{"name":"Verak Lith","rarity":"uncommon","id":"verak-lith","subtitle":"Bosses","details":"A mighty dragonkin experiment in Dragonkin Laboratory, breathing dragonfire across a shattered arena floor.","image":"https://runescape.wiki/images/thumb/Verak_Lith.png/640px-Verak_Lith.png"},{"name":"Crassian Leviathan","rarity":"uncommon","id":"crassian-leviathan","subtitle":"Bosses","details":"A huge crassian rising from the Shadow Reef's waters to snap, sweep and flood the arena with poison.","image":"https://runescape.wiki/images/thumb/Crassian_Leviathan.png/640px-Crassian_Leviathan.png"},{"name":"Elvarg","rarity":"uncommon","id":"elvarg","subtitle":"Bosses","details":"The green dragon of Crandor who destroyed the island and is faced at the climax of the Dragon Slayer quest.","image":"https://runescape.wiki/images/thumb/Elvarg.png/640px-Elvarg.png"},{"name":"Bork","rarity":"uncommon","id":"bork","subtitle":"Bosses","details":"A powerful ork in the Chaos Tunnels, fought once a day alongside his legion of loyal ork followers in battle.","image":"https://runescape.wiki/images/thumb/Bork.png/640px-Bork.png"},{"name":"Penance Queen","rarity":"uncommon","id":"penance-queen","subtitle":"Bosses","details":"The queen of the penance monsters at Barbarian Assault, defeated with omega eggs by a coordinated team.","image":"https://runescape.wiki/images/Penance_Queen.png"},{"name":"Pieces of Hate","rarity":"uncommon","id":"pieces-of-hate","subtitle":"Quests","details":"Rabid Jack returns to Mos Le'Harmless as zombie pirates, braindeath rum and a sea kraken collide. The finale of the Pirate quest series.","image":"https://runescape.wiki/images/thumb/Pieces_of_Hate.png/640px-Pieces_of_Hate.png?dde6f"},{"name":"The Lord of Vampyrium","rarity":"uncommon","id":"the-lord-of-vampyrium","subtitle":"Quests","details":"Storm Castle Drakan with the Myreque to face Lord Drakan himself atop his castle, as the vampyre storyline reaches its turning point.","image":"https://runescape.wiki/images/thumb/The_Lord_of_Vampyrium.png/640px-The_Lord_of_Vampyrium.png?50704"},{"name":"Death Plateau","rarity":"uncommon","id":"death-plateau","subtitle":"Quests","details":"Help Burthorpe's soldiers find a safe route to Death Plateau so supplies can bypass the troll stronghold blocking the mountain path.","image":"https://runescape.wiki/images/thumb/Death_Plateau.png/640px-Death_Plateau.png?7063d"},{"name":"Troll Stronghold","rarity":"uncommon","id":"troll-stronghold","subtitle":"Quests","details":"Rescue Godric from the Troll Stronghold prison below Death Plateau, climbing past thrower trolls and the generals who guard it.","image":"https://runescape.wiki/images/thumb/Troll_Stronghold.png/640px-Troll_Stronghold.png?a801c"},{"name":"Eadgar's Ruse","rarity":"uncommon","id":"eadgar-s-ruse","subtitle":"Quests","details":"Help Eadgar in Trollheim gather goutweed from the troll kitchens, using a fake parrot and a spicy sauce to fool the cooks.","image":"https://runescape.wiki/images/thumb/Eadgar%27s_Ruse.png/640px-Eadgar%27s_Ruse.png?85640"},{"name":"My Arm's Big Adventure","rarity":"uncommon","id":"my-arm-s-big-adventure","subtitle":"Quests","details":"Take the troll My Arm to Trollheim's rooftop garden and teach him to grow goutweed, despite goats, disease and a giant bird attack.","image":"https://runescape.wiki/images/thumb/My_Arm%27s_Big_Adventure.png/640px-My_Arm%27s_Big_Adventure.png?a04d1"},{"name":"Olaf's Quest","rarity":"uncommon","id":"olaf-s-quest","subtitle":"Quests","details":"Follow Olaf Hradson's treasure map from Rellekka through a shipwreck and a windswept dungeon to the lost Brine Rat Cavern hoard.","image":"https://runescape.wiki/images/thumb/Olaf%27s_Quest.png/640px-Olaf%27s_Quest.png?3a52b"},{"name":"The Eyes of Glouphrie","rarity":"uncommon","id":"the-eyes-of-glouphrie","subtitle":"Quests","details":"Help Brimstail and Hazelmere in the Gnome Stronghold, solve the disc machine, and expose a spy watching through a strange creature.","image":"https://runescape.wiki/images/thumb/The_Eyes_of_Glouphrie.png/640px-The_Eyes_of_Glouphrie.png?5ce3c"},{"name":"The Path of Glouphrie","rarity":"uncommon","id":"the-path-of-glouphrie","subtitle":"Quests","details":"Journey below Yanille to the poison waste sewers, aid the spirit Yewnock, and confront the warped creatures guarding his machine.","image":"https://runescape.wiki/images/thumb/The_Path_of_Glouphrie.png/640px-The_Path_of_Glouphrie.png?1fda2"},{"name":"A Fairy Tale I - Growing Pains","rarity":"uncommon","id":"a-fairy-tale-i-growing-pains","subtitle":"Quests","details":"Help Martin the Master Gardener when crops fail across Gielinor, recover his magic secateurs, and face the Tanglefoot in Zanaris.","image":"https://runescape.wiki/images/thumb/A_Fairy_Tale_I_-_Growing_Pains.png/640px-A_Fairy_Tale_I_-_Growing_Pains.png?41b02"},{"name":"A Fairy Tale II - Cure a Queen","rarity":"uncommon","id":"a-fairy-tale-ii-cure-a-queen","subtitle":"Quests","details":"Travel the fairy ring network to help the Fairy Queen recover from illness, gathering her secateurs and fighting a travelling orc.","image":"https://runescape.wiki/images/thumb/A_Fairy_Tale_II_-_Cure_a_Queen.png/640px-A_Fairy_Tale_II_-_Cure_a_Queen.png?3bc0b"},{"name":"A Fairy Tale III - Battle at Ork's Rift","rarity":"uncommon","id":"a-fairy-tale-iii-battle-at-ork-s-rift","subtitle":"Quests","details":"Join the Fairy Resistance against the Fairy Godfather, grow tooth creatures, and fight for Ork's Rift and Zanaris itself.","image":"https://runescape.wiki/images/thumb/A_Fairy_Tale_Part_III_-_Battle_at_Ork%27s_Rift.png/640px-A_Fairy_Tale_Part_III_-_Battle_at_Ork%27s_Rift.png?269fe"},{"name":"Rum Deal","rarity":"uncommon","id":"rum-deal","subtitle":"Quests","details":"Help Captain Braindeath brew his famous rum on Braindeath Island, gathering sluglings, swamp paste and a very holy wrench.","image":"https://runescape.wiki/images/thumb/Rum_Deal.png/640px-Rum_Deal.png?47ce5"},{"name":"Cabin Fever","rarity":"uncommon","id":"cabin-fever","subtitle":"Quests","details":"Sail with Bill Teach to Mos Le'Harmless, sabotage a rival pirate ship with a cannon, and settle Captain Donnie's feud at sea.","image":"https://runescape.wiki/images/thumb/Cabin_Fever.png/640px-Cabin_Fever.png?d562a"},{"name":"The Great Brain Robbery","rarity":"uncommon","id":"the-great-brain-robbery","subtitle":"Quests","details":"Defend Harmony Island from zombie pirates led by Mi-Gor, build a prayer-powered weapon, and reclaim the monks' stolen brains.","image":"https://runescape.wiki/images/thumb/The_great_brain_robbery.png/640px-The_great_brain_robbery.png?28a5a"},{"name":"Rocking Out","rarity":"uncommon","id":"rocking-out","subtitle":"Quests","details":"Break into the Rock Island Prison, earn a pirate's marks from Wanda the Fish, and piece together Rabid Jack's lost story.","image":"https://runescape.wiki/images/thumb/Rocking_Out.png/640px-Rocking_Out.png"},{"name":"Kennith's Concerns","rarity":"uncommon","id":"kennith-s-concerns","subtitle":"Quests","details":"Help Kennith in Witchaven, where villagers act strangely, sea slugs control minds, and a mother asks for aid from beneath the town.","image":"https://runescape.wiki/images/thumb/Kennith%27s_Concerns.png/640px-Kennith%27s_Concerns.png?40934"},{"name":"Hunt for Red Raktuber","rarity":"uncommon","id":"hunt-for-red-raktuber","subtitle":"Quests","details":"Infiltrate the penguin submarine Red Raktuber near Witchaven, gather its crew's secrets, and escape before the penguins strike.","image":"https://runescape.wiki/images/thumb/Hunt_for_Red_Raktuber.png/640px-Hunt_for_Red_Raktuber.png?4dfe0"},{"name":"Cold War","rarity":"uncommon","id":"cold-war","subtitle":"Quests","details":"Join the PBJ agent Larry to infiltrate penguin outposts in the iceberg and Ardougne Zoo, wearing a clockwork penguin suit.","image":"https://runescape.wiki/images/thumb/Cold_War.png/640px-Cold_War.png?9bfa9"},{"name":"The Hunt for Surok","rarity":"uncommon","id":"the-hunt-for-surok","subtitle":"Quests","details":"Track Surok Magis through the Chaos Tunnels below Varrock, follow his portals, and defeat Bork, the ork he summons to fight you.","image":"https://runescape.wiki/images/thumb/Surok_start_point.png/640px-Surok_start_point.png?6eadf"},{"name":"Back to the Freezer","rarity":"uncommon","id":"back-to-the-freezer","subtitle":"Quests","details":"Travel back in time with Chuck the penguin, stop the PBJ from rewriting history, and face a paradox aboard an iceberg outpost.","image":"https://runescape.wiki/images/thumb/Back_to_the_Freezer.png/640px-Back_to_the_Freezer.png?219ad"},{"name":"Rellekka","rarity":"uncommon","id":"rellekka","subtitle":"Locations","details":"The Fremennik capital on the north coast, a longhall town of trials, docks and mountain camps, gateway to Waterbirth and Lunar seas.","image":"https://runescape.wiki/images/thumb/Rellekka.png/640px-Rellekka.png"},{"name":"Lunar Isle","rarity":"uncommon","id":"lunar-isle","subtitle":"Locations","details":"An island in the far north-west seas, home of the Moon Clan, with an astral altar, flax fields and a town built over pirate seas.","image":"https://runescape.wiki/images/thumb/Lunar_Isle.png/640px-Lunar_Isle.png"},{"name":"Ape Atoll","rarity":"uncommon","id":"ape-atoll","subtitle":"Locations","details":"A tropical island ruled by intelligent apes, with a temple, a greegree disguise, a dangerous tunnel and the ape agility course.","image":"https://runescape.wiki/images/thumb/Ape_Atoll.png/640px-Ape_Atoll.png"},{"name":"Pollnivneach","rarity":"uncommon","id":"pollnivneach","subtitle":"Locations","details":"A desert town in the Kharidian Desert split between the Menaphites and the Bandit Camp, with a well, a kebab shop and rooftop courses.","image":"https://runescape.wiki/images/thumb/Pollnivneach.png/640px-Pollnivneach.png"},{"name":"Nardah","rarity":"uncommon","id":"nardah","subtitle":"Locations","details":"A small desert town east of Pollnivneach, built around a fountain and the statue of Elidinis, with a bank, a herblore shop and a shrine.","image":"https://runescape.wiki/images/thumb/Nardah.png/640px-Nardah.png"},{"name":"Sophanem","rarity":"uncommon","id":"sophanem","subtitle":"Locations","details":"A desert city on the River Elid, twin to Menaphos across the water, known for plagues, cats, pyramids and the Sophanem Slayer Dungeon.","image":"https://runescape.wiki/images/thumb/Sophanem.png/640px-Sophanem.png"},{"name":"Burgh de Rott","rarity":"uncommon","id":"burgh-de-rott","subtitle":"Locations","details":"A ruined town in southern Morytania, besieged by vampyres, rebuilt by travellers with a bank, a furnace and a base for Temple Trekking.","image":"https://runescape.wiki/images/thumb/Burgh_de_Rott.png/640px-Burgh_de_Rott.png"},{"name":"Port Phasmatys","rarity":"uncommon","id":"port-phasmatys","subtitle":"Locations","details":"A ghost port in northern Morytania, where undead sailors pay Ecto-tokens to enter and brew ectoplasm beside a haunted farming patch.","image":"https://runescape.wiki/images/thumb/Port_Phasmatys.png/640px-Port_Phasmatys.png"},{"name":"Slayer Tower","rarity":"uncommon","id":"slayer-tower","subtitle":"Locations","details":"A dark tower north-west of Canifis filled with Slayer monsters, chained hands and gargoyles, topped by Markus and his Slayer contracts.","image":"https://runescape.wiki/images/thumb/Slayer_tower_building.png/640px-Slayer_tower_building.png"},{"name":"Oo'glog","rarity":"uncommon","id":"oo-glog","subtitle":"Locations","details":"An ogre spa town south of Yanille, with thermal pools, a meat shop and balloon travel, opened to travellers after As a First Resort.","image":"https://runescape.wiki/images/thumb/Oo%27glog.png/640px-Oo%27glog.png"},{"name":"Grand Tree","rarity":"uncommon","id":"grand-tree","subtitle":"Locations","details":"A huge tree in the Tree Gnome Stronghold, home to King Narnode, gnome glider pilots, shops and restaurants spread across its branches.","image":"https://runescape.wiki/images/thumb/GrandTree.png/640px-GrandTree.png"},{"name":"Lletya","rarity":"uncommon","id":"lletya","subtitle":"Locations","details":"An elven town in Tirannwn founded by Eluned, with crystal shops, a dye shop and a shortcut back for travellers in the elven quest series.","image":"https://runescape.wiki/images/thumb/Lletya.png/640px-Lletya.png"},{"name":"Karamja","rarity":"uncommon","id":"karamja","subtitle":"Locations","details":"A tropical island south of Port Sarim, with a volcano, a banana plantation, jungles, a dungeon and ports at Musa Point and Brimhaven.","image":"https://runescape.wiki/images/thumb/Karamja.png/640px-Karamja.png"},{"name":"Ashdale","rarity":"uncommon","id":"ashdale","subtitle":"Locations","details":"A small island town north-west of the mainland, where new adventurers begin, with a harbour, a church and the cradle of a world event.","image":"https://runescape.wiki/images/thumb/Ashdale.png/640px-Ashdale.png"},{"name":"Neitiznot","rarity":"uncommon","id":"neitiznot","subtitle":"Locations","details":"A Fremennik island town of yak pastures, longhalls and honour guards, ruled by Mawnis Burowgar across the bridges from Jatizso.","image":"https://runescape.wiki/images/thumb/Neitiznot_scenery.png/640px-Neitiznot_scenery.png"},{"name":"Dorgesh-Kaan","rarity":"uncommon","id":"dorgesh-kaan","subtitle":"Locations","details":"An underground city of cave goblins beneath Lumbridge, lit by magic, with markets, a council and a train link to Keldagrim.","image":"https://runescape.wiki/images/thumb/Dorgesh-Kaan.png/640px-Dorgesh-Kaan.png"},{"name":"Famine","rarity":"uncommon","id":"famine","subtitle":"Gods & NPCs","details":"One of the Four Horsemen summoned at holiday events, a gaunt rider whose arrival heralds hunger, blight and empty stores.","image":"https://runescape.wiki/images/thumb/Famine.png/640px-Famine.png"},{"name":"Pestilence","rarity":"uncommon","id":"pestilence","subtitle":"Gods & NPCs","details":"One of the Four Horsemen, a sickly rider associated with plague and disease who appears alongside War, Famine and Death.","image":"https://runescape.wiki/images/thumb/Pestilence.png/640px-Pestilence.png"},{"name":"Party Pete","rarity":"uncommon","id":"party-pete","subtitle":"Gods & NPCs","details":"Host of the Falador Party Room, a cheerful man with an afro who oversees drop parties where balloons rain down on guests.","image":"https://runescape.wiki/images/thumb/Party_Pete.png/640px-Party_Pete.png"},{"name":"Postie Pete","rarity":"uncommon","id":"postie-pete","subtitle":"Gods & NPCs","details":"A skeleton postman who delivers letters across Gielinor and appears in postbag features, court cases and random events.","image":"https://runescape.wiki/images/thumb/Postie_Pete.png/640px-Postie_Pete.png"},{"name":"Evil Dave","rarity":"uncommon","id":"evil-dave","subtitle":"Gods & NPCs","details":"An aspiring villain in black who lives in his mother's Edgeville basement, dreams of evil, and adores a spicy hell-rat stew.","image":"https://runescape.wiki/images/thumb/Evil_Dave_%28Shadow_of_the_Storm%29.png/640px-Evil_Dave_%28Shadow_of_the_Storm%29.png"},{"name":"Thok","rarity":"uncommon","id":"thok","subtitle":"Gods & NPCs","details":"A Fremennik warrior of Daemonheim who bashes through its floors head-first and tells tall tales of his heroic delving.","image":"https://runescape.wiki/images/thumb/Thok_meeting_pretty_lass.png/640px-Thok_meeting_pretty_lass.png"},{"name":"Sir Tiffy Cashien","rarity":"uncommon","id":"sir-tiffy-cashien","subtitle":"Gods & NPCs","details":"Head of recruitment for the Temple Knights in Falador park, a kindly old knight who sends agents on secretive missions.","image":"https://runescape.wiki/images/thumb/Sir_Tiffy_Cashien.png/640px-Sir_Tiffy_Cashien.png"},{"name":"King Roald","rarity":"uncommon","id":"king-roald","subtitle":"Gods & NPCs","details":"King Roald Remanis III, ruler of Misthalin from Varrock Palace, who governs his kingdom beside Queen Ellamaria.","image":"https://runescape.wiki/images/thumb/King_Roald.png/640px-King_Roald.png"},{"name":"Queen Ellamaria","rarity":"uncommon","id":"queen-ellamaria","subtitle":"Gods & NPCs","details":"Queen of Misthalin and wife of King Roald, a former barbarian adventurer who tends Varrock's palace garden.","image":"https://runescape.wiki/images/thumb/Ellamaria.png/640px-Ellamaria.png"},{"name":"Reldo","rarity":"uncommon","id":"reldo","subtitle":"Gods & NPCs","details":"Librarian of Varrock Palace, a scholarly keeper of rare tomes who aids adventurers in quests of history and legend.","image":"https://runescape.wiki/images/thumb/Reldo.png/640px-Reldo.png"},{"name":"Osman","rarity":"uncommon","id":"osman","subtitle":"Gods & NPCs","details":"Spymaster of Al Kharid, a cunning intelligence chief who directs agents, plots and covert work for the Emir's palace.","image":"https://runescape.wiki/images/thumb/Osman_%28Recipe_for_Disaster%29.png/640px-Osman_%28Recipe_for_Disaster%29.png"},{"name":"Meg","rarity":"uncommon","id":"meg","subtitle":"Gods & NPCs","details":"An aspiring adventurer found in ports who asks for advice each week and bungles her way toward becoming a hero.","image":"https://runescape.wiki/images/thumb/Meg.png/640px-Meg.png"},{"name":"Abyssal Whip","rarity":"uncommon","id":"abyssal-whip","subtitle":"Gear","details":"Tier 70 main-hand melee weapon dropped by abyssal demons in the Slayer Tower, for years the classic one-handed weapon of choice.","image":"https://runescape.wiki/images/thumb/Abyssal_whip_detail.png/512px-Abyssal_whip_detail.png"},{"name":"Dragonfire Shield","rarity":"uncommon","id":"dragonfire-shield","subtitle":"Gear","details":"Tier 70 anti-dragon shield made by joining a draconic visage to an anti-dragon shield, absorbing dragonfire into charges.","image":"https://runescape.wiki/images/thumb/Dragonfire_shield_%28uncharged%29_detail.png/512px-Dragonfire_shield_%28uncharged%29_detail.png"},{"name":"Elysian Spirit Shield","rarity":"uncommon","id":"elysian-spirit-shield","subtitle":"Gear","details":"Tier 75 Ranged shield made from an elysian sigil and a blessed spirit shield, often reducing incoming damage by a quarter.","image":"https://runescape.wiki/images/thumb/Elysian_spirit_shield_detail.png/512px-Elysian_spirit_shield_detail.png"},{"name":"Arcane Spirit Shield","rarity":"uncommon","id":"arcane-spirit-shield","subtitle":"Gear","details":"Tier 75 Magic shield made from an arcane sigil attached to a blessed spirit shield with help from the Holy Elves.","image":"https://runescape.wiki/images/thumb/Arcane_spirit_shield_detail.png/512px-Arcane_spirit_shield_detail.png"},{"name":"Spectral Spirit Shield","rarity":"uncommon","id":"spectral-spirit-shield","subtitle":"Gear","details":"Tier 75 shield made from a spectral sigil and a blessed spirit shield, valued for its strong prayer bonus.","image":"https://runescape.wiki/images/thumb/Spectral_spirit_shield_detail.png/512px-Spectral_spirit_shield_detail.png"},{"name":"Amulet of Souls","rarity":"uncommon","id":"amulet-of-souls","subtitle":"Gear","details":"Tier 99 neck jewellery made by enchanting an onyx amulet, occasionally healing extra from Soul Split and protection prayers.","image":"https://runescape.wiki/images/thumb/Amulet_of_souls_detail.png/512px-Amulet_of_souls_detail.png"},{"name":"Ring of Death","rarity":"uncommon","id":"ring-of-death","subtitle":"Gear","details":"Tier 99 ring made by enchanting a hydrix ring, letting its wearer cheat death and return at a cost in charges.","image":"https://runescape.wiki/images/thumb/Ring_of_death_detail.png/512px-Ring_of_death_detail.png"},{"name":"Deathtouch Bracelet","rarity":"uncommon","id":"deathtouch-bracelet","subtitle":"Gear","details":"Tier 99 gloves made by enchanting a hydrix bracelet, reflecting a share of damage taken back onto attackers.","image":"https://runescape.wiki/images/thumb/Deathtouch_bracelet_detail.png/512px-Deathtouch_bracelet_detail.png"},{"name":"Cinderbane Gloves","rarity":"uncommon","id":"cinderbane-gloves","subtitle":"Gear","details":"Tier 85 hybrid gloves dropped by lost lands dinosaurs and Solak's grove creatures, poisoning weapons with cinderbane venom.","image":"https://runescape.wiki/images/thumb/Cinderbane_gloves_detail.png/512px-Cinderbane_gloves_detail.png"},{"name":"Death Lotus Armour","rarity":"uncommon","id":"death-lotus-armour","subtitle":"Gear","details":"Tier 85 Ranged tank armour made in a player-owned port from lacquer gathered by adventurers sailing the Wushanko Isles.","image":"https://runescape.wiki/images/thumb/Death_Lotus_chestplate_detail.png/512px-Death_Lotus_chestplate_detail.png"},{"name":"Dragon Scimitar","rarity":"uncommon","id":"dragon-scimitar","subtitle":"Gear","details":"Tier 60 main-hand melee weapon bought after Monkey Madness on Ape Atoll, the classic fast trainer for Strength levels.","image":"https://runescape.wiki/images/thumb/Dragon_scimitar_detail.png/512px-Dragon_scimitar_detail.png"},{"name":"Dragon Claws","rarity":"uncommon","id":"dragon-claws","subtitle":"Gear","details":"Tier 60 main-hand melee weapon dropped by tormented demons, famous for its four-hit special attack in player combat.","image":"https://runescape.wiki/images/thumb/Dragon_claw_detail.png/512px-Dragon_claw_detail.png"},{"name":"Dark Bow","rarity":"uncommon","id":"dark-bow","subtitle":"Gear","details":"Tier 70 two-handed bow dropped by dark beasts, firing two arrows at once and loosing a feared special attack in PvP.","image":"https://runescape.wiki/images/thumb/Dark_bow_detail.png/512px-Dark_bow_detail.png"},{"name":"Dharok's Greataxe","rarity":"uncommon","id":"dharok-s-greataxe","subtitle":"Gear","details":"Tier 70 two-handed Barrows weapon from Dharok the Wretched in the Barrows crypts, hitting harder as its wielder weakens.","image":"https://runescape.wiki/images/thumb/Dharok%27s_greataxe_detail.png/512px-Dharok%27s_greataxe_detail.png"},{"name":"Guthan's Warspear","rarity":"uncommon","id":"guthan-s-warspear","subtitle":"Gear","details":"Tier 70 Barrows spear from Guthan the Infested in the Barrows crypts, able to heal its wielder while wearing his full set.","image":"https://runescape.wiki/images/thumb/Guthan%27s_warspear_detail.png/512px-Guthan%27s_warspear_detail.png"},{"name":"Verac's Flail","rarity":"uncommon","id":"verac-s-flail","subtitle":"Gear","details":"Tier 70 Barrows flail from Verac the Defiled in the Barrows crypts, able to hit through armour and prayer with his full set.","image":"https://runescape.wiki/images/thumb/Verac%27s_flail_detail.png/512px-Verac%27s_flail_detail.png"},{"name":"Ahrim's Staff","rarity":"uncommon","id":"ahrim-s-staff","subtitle":"Gear","details":"Tier 70 Barrows staff from Ahrim the Blighted in the Barrows crypts, the classic two-handed Magic weapon of the set.","image":"https://runescape.wiki/images/thumb/Ahrim%27s_staff_detail.png/512px-Ahrim%27s_staff_detail.png"},{"name":"Karil's Crossbow","rarity":"uncommon","id":"karil-s-crossbow","subtitle":"Gear","details":"Tier 70 Barrows crossbow from Karil the Tainted in the Barrows crypts, firing bolt racks instead of ordinary bolts.","image":"https://runescape.wiki/images/thumb/Karil%27s_crossbow_detail.png/512px-Karil%27s_crossbow_detail.png"},{"name":"Torag's Hammer","rarity":"uncommon","id":"torag-s-hammer","subtitle":"Gear","details":"Tier 70 Barrows hammer from Torag the Corrupted in the Barrows crypts, part of the toughest tank set of the brothers.","image":"https://runescape.wiki/images/thumb/Torag%27s_hammer_detail.png/512px-Torag%27s_hammer_detail.png"},{"name":"Akrisae's War Mace","rarity":"uncommon","id":"akrisae-s-war-mace","subtitle":"Gear","details":"Tier 70 Barrows mace from Akrisae the Doomed, unlocked by Ritual of the Mahjarrat, converting prayer points in his set.","image":"https://runescape.wiki/images/thumb/Akrisae%27s_war_mace_detail.png/512px-Akrisae%27s_war_mace_detail.png"},{"name":"Zaryte Bow","rarity":"uncommon","id":"zaryte-bow","subtitle":"Gear","details":"Tier 80 two-handed bow dropped by Nex in the Ancient Prison, needing no arrows and degrading as it fires its shots.","image":"https://runescape.wiki/images/thumb/Zaryte_bow_detail.png/512px-Zaryte_bow_detail.png"},{"name":"Saradomin Sword","rarity":"uncommon","id":"saradomin-sword","subtitle":"Gear","details":"Tier 70 two-handed sword dropped by Commander Zilyana in the God Wars Dungeon, swinging fast with a lightning special.","image":"https://runescape.wiki/images/thumb/Saradomin_sword_detail.png/512px-Saradomin_sword_detail.png"},{"name":"Bloodveld","rarity":"uncommon","id":"bloodveld","subtitle":"Monsters","details":"Bloodveld are fleshy Slayer monsters in the Slayer Tower and Meiyerditch tunnels, attacking with magic-based melee strikes.","image":"https://runescape.wiki/images/thumb/Bloodveld.png/640px-Bloodveld.png"},{"name":"Dust devil","rarity":"uncommon","id":"dust-devil","subtitle":"Monsters","details":"Dust devils are Slayer monsters in the Smoke Dungeon and Chaos Tunnels, obscuring vision with swirling clouds of dust.","image":"https://runescape.wiki/images/thumb/Dust_devil.png/640px-Dust_devil.png"},{"name":"Aberrant spectre","rarity":"uncommon","id":"aberrant-spectre","subtitle":"Monsters","details":"Aberrant spectres are undead Slayer monsters in the Slayer Tower and Pollnivneach dungeon, requiring a nose peg to face.","image":"https://runescape.wiki/images/thumb/Aberrant_spectre.png/640px-Aberrant_spectre.png"},{"name":"Spiritual warrior","rarity":"uncommon","id":"spiritual-warrior","subtitle":"Monsters","details":"Spiritual warriors are ghostly fighters in the God Wars Dungeon, fighting eternally for the god whose banner they carry.","image":"https://runescape.wiki/images/thumb/Spiritual_warrior_%28Zamorak%29.png/640px-Spiritual_warrior_%28Zamorak%29.png"},{"name":"Spiritual mage","rarity":"uncommon","id":"spiritual-mage","subtitle":"Monsters","details":"Spiritual mages are ghostly spellcasters in the God Wars Dungeon, with Saradomin's mages known for dropping dragon boots.","image":"https://runescape.wiki/images/thumb/Spiritual_mage_%28Zamorak%29.png/640px-Spiritual_mage_%28Zamorak%29.png"},{"name":"Ice strykewyrm","rarity":"uncommon","id":"ice-strykewyrm","subtitle":"Monsters","details":"Ice strykewyrms burrow under the Ice Plateau in the Wilderness, surfacing only when a Slayer task brings a hunter near.","image":"https://runescape.wiki/images/thumb/Ice_strykewyrm.png/640px-Ice_strykewyrm.png"},{"name":"Desert strykewyrm","rarity":"uncommon","id":"desert-strykewyrm","subtitle":"Monsters","details":"Desert strykewyrms hide beneath the sands east of Al Kharid, bursting out to strike travellers crossing the desert heat.","image":"https://runescape.wiki/images/thumb/Desert_strykewyrm.png/640px-Desert_strykewyrm.png"},{"name":"Crystal shapeshifter","rarity":"uncommon","id":"crystal-shapeshifter","subtitle":"Monsters","details":"Crystal shapeshifters are elven creatures on Tarddiad that shift between melee, ranged and magic crystal armour forms.","image":"https://runescape.wiki/images/thumb/Crystal_Shapeshifter.png/640px-Crystal_Shapeshifter.png"},{"name":"Airut","rarity":"uncommon","id":"airut","subtitle":"Monsters","details":"Airuts are pig-like creatures from Mazcab also found in Kuradal's Dungeon, pounding the ground with powerful melee blows.","image":"https://runescape.wiki/images/thumb/Airut.png/640px-Airut.png"},{"name":"Edimmu","rarity":"uncommon","id":"edimmu","subtitle":"Monsters","details":"Edimmu are powerful undead spirits in the Prifddinas Slayer dungeon, requiring a high Slayer level and a task to fight.","image":"https://runescape.wiki/images/thumb/Edimmu.png/640px-Edimmu.png"},{"name":"Soulgazer","rarity":"uncommon","id":"soulgazer","subtitle":"Monsters","details":"Soulgazers are Stalker creatures dominated by a single huge eye, floating hunters that strike with a piercing magical gaze.","image":"https://runescape.wiki/images/thumb/Soulgazer.png/640px-Soulgazer.png"},{"name":"Nightmare","rarity":"uncommon","id":"nightmare","subtitle":"Monsters","details":"Nightmares are shadowy creatures of twisted spikes and claws, haunting dark places and feeding on fear and despair alike.","image":"https://runescape.wiki/images/thumb/Nightmare.png/640px-Nightmare.png"},{"name":"Dragonstone dragon","rarity":"uncommon","id":"dragonstone-dragon","subtitle":"Monsters","details":"Dragonstone dragons are gemstone dragons with purple crystalline scales, breathing purple dragonfire in powerful bursts.","image":"https://runescape.wiki/images/thumb/Dragonstone_dragon.png/640px-Dragonstone_dragon.png"},{"name":"Blood nihil","rarity":"uncommon","id":"blood-nihil","subtitle":"Monsters","details":"Blood nihil are nihil creatures made from blood energy on Freneskae, draining health from victims to heal themselves.","image":"https://runescape.wiki/images/thumb/Blood_nihil.png/640px-Blood_nihil.png"},{"name":"Green Partyhat","rarity":"uncommon","id":"green-partyhat","subtitle":"Items","details":"A green paper partyhat from the earliest Christmas crackers, surviving as one of six discontinued party colours.","image":"https://runescape.wiki/images/thumb/Green_partyhat_detail.png/640px-Green_partyhat_detail.png"},{"name":"Yellow Partyhat","rarity":"uncommon","id":"yellow-partyhat","subtitle":"Items","details":"A yellow paper partyhat pulled from a Christmas cracker long ago, bright as the wealth its collectors trade it for.","image":"https://runescape.wiki/images/Yellow_partyhat_detail.png"},{"name":"Black Santa Hat","rarity":"uncommon","id":"black-santa-hat","subtitle":"Items","details":"A dark twist on the classic Santa hat, first won as a rare prize from festive crackers during a Christmas season.","image":"https://runescape.wiki/images/Black_Santa_hat_detail.png"},{"name":"Golden Partyhat","rarity":"uncommon","id":"golden-partyhat","subtitle":"Items","details":"A golden paper crown earned by gathering shards during the Golden Partyhat Hunt that marked twenty years of adventure.","image":"https://runescape.wiki/images/thumb/Golden_partyhat_detail.png/640px-Golden_partyhat_detail.png"},{"name":"Barrows Dye","rarity":"uncommon","id":"barrows-dye","subtitle":"Items","details":"A dye from elite Treasure Trails that recolours high-level gear in the earthy olive tones of the Barrows brothers.","image":"https://runescape.wiki/images/thumb/Barrows_dye_detail.png/640px-Barrows_dye_detail.png"},{"name":"Shadow Dye","rarity":"uncommon","id":"shadow-dye","subtitle":"Items","details":"A dye from elite Treasure Trails that recolours high-level gear in a dark shadowy purple, consumed when applied.","image":"https://runescape.wiki/images/thumb/Shadow_dye_detail.png/640px-Shadow_dye_detail.png"},{"name":"Holly Wreath","rarity":"uncommon","id":"holly-wreath","subtitle":"Items","details":"A festive wreath first handed out as an exceptionally rare prize from festive crackers, prized as a holiday status symbol.","image":"https://runescape.wiki/images/thumb/Holly_wreath_detail.png/640px-Holly_wreath_detail.png"},{"name":"Clan Wars","rarity":"uncommon","id":"clan-wars","subtitle":"Activities","details":"A clan battle arena in the Gamers' Grotto where groups clash in custom wars, free-for-all fights and safe duels.","image":"https://runescape.wiki/images/thumb/Clan_Wars.png/640px-Clan_Wars.png"},{"name":"Stealing Creation","rarity":"uncommon","id":"stealing-creation","subtitle":"Activities","details":"A creation and combat activity where teams harvest sacred clay, craft gear in kilns and fight for the most points.","image":"https://runescape.wiki/images/thumb/Stealing_Creation_game_arena.png/640px-Stealing_Creation_game_arena.png"},{"name":"Fist of Guthix","rarity":"uncommon","id":"fist-of-guthix","subtitle":"Activities","details":"A one-versus-one hunt in a wild arena, where a hunted player charges a stone while the hunter tries to stop them.","image":"https://runescape.wiki/images/thumb/Fist_of_Guthix.png/640px-Fist_of_Guthix.png"},{"name":"Sinkholes","rarity":"uncommon","id":"sinkholes","subtitle":"Activities","details":"A Dungeoneering card activity in a shifting sinkhole, racing other delvers for lamps, tokens and the best hoard prize.","image":"https://runescape.wiki/images/thumb/Sinkhole_entrance.png/640px-Sinkhole_entrance.png"},{"name":"Tears of Guthix","rarity":"uncommon","id":"tears-of-guthix","subtitle":"Activities","details":"A weekly activity in a Lumbridge cave, collecting blue tears from weeping walls for the snake Juna to gain experience.","image":"https://runescape.wiki/images/thumb/TOG_cave.png/640px-TOG_cave.png"},{"name":"Penguin Hide and Seek","rarity":"uncommon","id":"penguin-hide-and-seek","subtitle":"Activities","details":"A weekly spy hunt tracking ten penguins disguised across Gielinor, reported by agents for points and rewards.","image":"https://runescape.wiki/images/thumb/Penguin.png/640px-Penguin.png"},{"name":"Rush of Blood","rarity":"uncommon","id":"rush-of-blood","subtitle":"Activities","details":"A Slayer trial in Prifddinas where fighters clear escalating waves of monsters against the clock for titles and loot.","image":"https://runescape.wiki/images/thumb/Rush_of_Blood.png/640px-Rush_of_Blood.png?2c6fc"},{"name":"Heist","rarity":"uncommon","id":"heist","subtitle":"Activities","details":"A guards-versus-robbers activity where robbers disguise themselves among villagers to steal loot from guarded houses.","image":"https://runescape.wiki/images/thumb/Heist.png/640px-Heist.png"},{"name":"Strength","rarity":"common","id":"strength","subtitle":"Skills","details":"Raw melee power. Higher Strength raises maximum melee hits and unlocks equipment, training spots, and strength-based shortcuts.","image":"https://runescape.wiki/images/thumb/Strength_cape_detail.png/640px-Strength_cape_detail.png"},{"name":"Defence","rarity":"common","id":"defence","subtitle":"Skills","details":"Training Defence reduces the sting of enemy attacks and unlocks stronger armour, letting warriors survive far tougher fights.","image":"https://runescape.wiki/images/thumb/Defence_cape_detail.png/640px-Defence_cape_detail.png"},{"name":"Constitution","rarity":"common","id":"constitution","subtitle":"Skills","details":"A measure of health and endurance. Higher Constitution raises maximum life points and the healing a character can benefit from.","image":"https://runescape.wiki/images/thumb/Constitution_cape_detail.png/640px-Constitution_cape_detail.png"},{"name":"Agility","rarity":"common","id":"agility","subtitle":"Skills","details":"Nimble movement across rooftop courses and shortcuts all over the world, restoring run energy faster with every level gained.","image":"https://runescape.wiki/images/thumb/Agility_cape_detail.png/640px-Agility_cape_detail.png"},{"name":"Thieving","rarity":"common","id":"thieving","subtitle":"Skills","details":"Pickpocketing, stalls, safecracking, and locked chests. Light fingers turn other people's pockets into a steady income.","image":"https://runescape.wiki/images/thumb/Thieving_cape_detail.png/640px-Thieving_cape_detail.png"}]});
